window.IBSEHS_NATIVE=[
{code:'A.1.1',page:1,theme:'A',title:nb('Inter-system communication','系统间通讯'),guidingQuestion:nb('How do the nervous and endocrine systems work together to regulate body systems and maintain homeostasis?','神经和内分泌系统如何共同调节身体系统并维持稳态？'),intro:nb('The body communicates through fast, precise neural pathways and slower, longer-lasting endocrine signals. Their coordination allows a single change in the environment to trigger rapid protective action and sustained regulation of energy, temperature, fluids and recovery.','身体通过快速而精准的神经通路，以及较慢但持续时间更长的内分泌信号进行通讯。两者的协调使环境变化能够同时引发快速保护反应和持续的能量、体温、体液与恢复调节。'),sections:[
ns('Communication systems',[nb('The nervous system transmits electrical impulses along neurones and uses neurotransmitters at synapses. The endocrine system releases hormones into the bloodstream; only target cells with suitable receptors respond.','神经系统沿神经元传递电脉冲，并在突触处使用神经递质。内分泌系统将激素释放到血液中，只有具有相应受体的靶细胞会响应。')],[nb('Nervous control is rapid, precise, localised and usually short-lived.','神经控制快速、精准、局部化，通常作用时间较短。'),nb('Endocrine control is slower, widespread and longer-lasting.','内分泌控制较慢、影响范围广、持续时间较长。')],[nb('Homeostasis','稳态', 'The maintenance of a stable internal environment within workable limits.','将内部环境维持在可工作的狭窄范围内。'),nb('Negative feedback','负反馈', 'A response that counters a change and returns the variable toward its normal range.','抵消变化，使变量回到正常范围的反馈。'),nb('Positive feedback','正反馈', 'A response that amplifies a change until a specific endpoint.','放大变化直至达到特定终点的反馈。')],{headers:[nb('Feature','特征'),nb('Nervous system','神经系统'),nb('Endocrine system','内分泌系统')],rows:[[nb('Signal','信号'),nb('Electrical impulses; neurotransmitters at synapses','神经元电脉冲；突触处神经递质'),nb('Hormones carried in blood','血液运输的激素')],[nb('Speed','速度'),nb('Milliseconds','毫秒级'),nb('Seconds to days','秒至天')],[nb('Effect','作用'),nb('Fast, precise, localised','快速、精准、局部'),nb('Slower, widespread, longer-lasting','较慢、广泛、持久')]]},[], [nb('At the start of a sprint, somatic motor output produces rapid skeletal-muscle contraction while adrenaline increases cardiovascular readiness and mobilises energy.','冲刺开始时，躯体运动输出使骨骼肌快速收缩，肾上腺素同时提高心血管准备程度并动员能量。')], [nb('Explain how nervous and endocrine control can act at different time scales.','解释神经控制和内分泌控制如何作用于不同时间尺度。')],[nb('Name the two main communication systems.','说出两种主要通讯系统。'),nb('Sequence stimulus, receptor, control centre, effector and response in a negative-feedback loop.','按刺激、受体、控制中心、效应器和反应排列负反馈过程。')])
,ns('Neural pathways and coordination',[nb('The central nervous system consists of the brain and spinal cord. It processes and interprets information and coordinates responses. The peripheral nervous system carries sensory information to the CNS and motor commands from it.','中枢神经系统由脑和脊髓组成，负责处理、解释信息并协调反应。周围神经系统将感觉信息传至中枢，并将运动指令传离中枢。')],[nb('Somatic pathways control voluntary skeletal muscle, such as deciding to jump.','躯体通路控制随意骨骼肌，例如决定起跳。'),nb('Autonomic pathways control glands, smooth muscle and cardiac muscle without conscious effort.','自主通路控制腺体、平滑肌和心肌，不需有意识努力。'),nb('The sympathetic division prepares the body for action or stress; the parasympathetic division supports recovery, digestion and energy conservation.','交感神经分支为行动或压力做准备；副交感神经分支支持恢复、消化和能量保存。')],[nb('CNS','中枢神经系统', 'Brain and spinal cord; integration and coordination.','脑和脊髓；整合与协调。'),nb('PNS','周围神经系统', 'Nerves outside the CNS that carry sensory and motor information.','中枢外的神经，传递感觉和运动信息。'),nb('Reflex','反射', 'A rapid automatic protective response integrated mainly at the spinal cord.','主要由脊髓整合的快速自动保护反应。')],[],[nb('After exercise, parasympathetic activity can support recovery while endocrine signals such as growth hormone and insulin support repair, energy regulation and longer-term adaptation.','运动后，副交感活动可帮助恢复；生长激素和胰岛素等内分泌信号则支持修复、能量调节和长期适应。')],[nb('Compare somatic and autonomic control in a sport context.','在运动情境中比较躯体控制和自主控制。')],[nb('Differentiate sympathetic and parasympathetic activity.','区分交感与副交感活动。'),nb('Explain how negative feedback supports homeostasis.','解释负反馈如何支持稳态。')])
],examFocus:[nb('Use the nervous/endocrine distinction and a real sporting example rather than memorising isolated gland names.','使用神经与内分泌的区分及真实运动例子，而不是孤立记忆腺体名称。')],quickCheck:[nb('Trace a stimulus through receptor → CNS → motor output → effector and add one endocrine response.','沿“感受器→中枢→运动输出→效应器”追踪刺激，再加入一个内分泌反应。')]},
{code:'A.1.2',page:2,theme:'A',title:nb('Intra-system communication','系统内通讯'),guidingQuestion:nb('How do organ systems work together within the body to support performance and homeostasis?','身体内的器官系统如何共同支持表现与稳态？'),intro:nb('Organ systems are interdependent. Nervous, endocrine, cardiovascular, respiratory, muscular and excretory systems exchange information and constrain one another so that the body can respond to changing demands without losing internal stability.','器官系统相互依存。神经、内分泌、心血管、呼吸、肌肉与排泄系统交换信息并相互制约，使身体能够响应变化需求，同时维持内部稳定。'),sections:[
ns('Systems working together',[nb('A nervous pathway is fast because electrical impulses travel along neurones and neurotransmitters cross synapses. An endocrine pathway is slower because hormones must be released and transported in the blood.','神经通路快速，因为电脉冲沿神经元传递，神经递质跨越突触。内分泌通路较慢，因为激素需要释放并通过血液运输。')],[nb('The cardiovascular and respiratory systems deliver oxygen and nutrients and remove carbon dioxide and heat.','心血管与呼吸系统输送氧气和营养物质，并移除二氧化碳与热量。'),nb('The muscular system uses oxygen and nutrients to produce force.','肌肉系统利用氧气和营养物质产生力。'),nb('The endocrine system adjusts energy availability, while the excretory system removes waste and excess water.','内分泌系统调节能量可用性，排泄系统清除废物和过量水分。')],[nb('Integration','整合', 'Coordinated activity across systems that supports performance and survival.','跨系统的协调活动，支持表现与生存。')],[],[nb('During exercise, breathing and circulation increase delivery of oxygen and nutrients, muscles use them to produce energy, and endocrine signals help regulate fuel.','运动时，呼吸与循环增加氧气和营养物质输送，肌肉利用这些物质产生能量，内分泌信号帮助调节燃料。')],[nb('Explain why no organ system works in isolation.','解释为什么器官系统不能孤立工作。')],[nb('Name two systems involved in thermoregulation.','指出参与体温调节的两个系统。')])
,ns('Feedback and integrated examples',[nb('Negative feedback is the most common control mechanism. It counters a deviation and stops when the normal range is restored. Positive feedback is rarer: it amplifies a change until a defined endpoint, such as blood clotting or childbirth, is reached.','负反馈是最常见的控制机制。它抵消偏离，并在正常范围恢复后停止。正反馈较少见：它把变化放大，直至达到凝血或分娩等特定终点。')],[nb('Thermoregulation in heat involves sensory detection, nervous control of sweating and vasodilation, and endocrine water conservation through ADH.','高温下的体温调节包括感觉检测、神经控制出汗与血管舒张，以及通过抗利尿激素进行的水分保存。'),nb('After a meal, pancreatic insulin helps cells take up glucose and storage occurs in the liver and muscles.','餐后，胰腺分泌的胰岛素帮助细胞摄取葡萄糖，肝脏和肌肉储存能量。'),nb('Fight or flight uses sympathetic nervous activity and adrenaline to raise heart rate, breathing, blood flow to muscles and available energy.','战斗或逃跑反应利用交感神经活动和肾上腺素，提高心率、呼吸、肌肉血流和可用能量。')],[nb('Thermoregulation','体温调节', 'Control of temperature through heat loss, heat production and circulation.','通过散热、产热和循环控制体温。'),nb('Eustress','积极压力', 'Useful challenge that energises and focuses performance.','有益的挑战，可激活并集中表现。')],[],[nb('A football player in a hot match sweats, vasodilates and shifts blood between the skin, muscles and other tissues. Explain the nervous and endocrine contributions.','足球运动员在高温比赛中出汗、血管舒张，并在皮肤、肌肉等组织间调整血流。解释其中神经和内分泌的作用。')],[nb('Compare negative and positive feedback with one example of each.','比较负反馈与正反馈，并各举一个例子。')],[nb('Why is integration important during exercise?','为什么运动中的系统整合很重要？')])
],examFocus:[nb('Use concrete examples such as thermoregulation, blood-glucose regulation or fight or flight to show system interaction.','用体温调节、血糖调节或战斗/逃跑反应等具体例子说明系统互动。')],quickCheck:[nb('Give one example of systems working together and explain how.','举出一个系统共同工作的例子并解释过程。')]},
{code:'A.1.3',page:3,theme:'A',title:nb('Nervous and endocrine control of movement','运动中的神经与内分泌控制'),guidingQuestion:nb('How do the nervous and endocrine systems control movement and physical performance?','神经和内分泌系统如何控制运动与身体表现？'),intro:nb('Movement begins with sensory information and a decision in the CNS, continues through motor output to an effector, and is refined by feedback. Hormones modify readiness, energy availability, strength, tissue repair and the physiological response to training.','运动始于感觉信息和中枢作出的决定，经运动输出到达效应器，并由反馈不断修正。激素调节准备状态、能量可用性、力量、组织修复以及训练后的生理反应。'),sections:[
ns('Voluntary movement and reflexes',[nb('A voluntary pathway has four linked stages: sensory input, CNS processing, motor output and effector response. Receptors detect light, sound, touch or position; the brain and spinal cord interpret the information; motor neurones carry commands to muscles or glands; the effector produces the response.','随意运动通路包含四个阶段：感觉输入、中枢处理、运动输出和效应器反应。感受器检测光、声、触觉或位置；脑和脊髓解释信息；运动神经元把指令传至肌肉或腺体；效应器产生反应。')],[nb('Reaction time is the interval from the stimulus to the start of movement.','反应时是从刺激出现到运动开始之间的时间。'),nb('A reflex is very fast, involuntary, protective and integrated mainly at the spinal cord. It can protect the body while the brain continues processing other information.','反射快速、不自主、保护性强，主要由脊髓整合。它可以在大脑处理其他信息时保护身体。')],[nb('Motor output','运动输出', 'Motor-neurone impulses sent from the CNS to an effector.','从中枢传向效应器的运动神经元冲动。'),nb('Feedback','反馈', 'Information about the movement returned to the CNS to adjust the next response.','关于运动的信息返回中枢，以调整下一次反应。')],[],[nb('In a knee-jerk response, tapping the patellar tendon stretches the quadriceps muscle spindle, information enters the spinal cord, and the quadriceps contracts so the lower leg moves forward.','在膝反射中，敲击髌腱使股四头肌肌梭被牵张，信息进入脊髓，股四头肌收缩，小腿向前运动。')],[nb('Distinguish a reflex from a voluntary movement using pathway and speed.','从通路和速度区分反射与随意运动。')],[nb('Trace a sprint start from stimulus to effector response.','追踪冲刺开始时的刺激到效应器反应。')])
,ns('Hormonal influences and sport applications',[nb('The cerebellum supports timing, balance, accuracy and error correction. Hormones influence the same performance through alertness, energy availability, muscle function, recovery and adaptation.','小脑支持时机、平衡、准确性和纠错。激素则通过警觉、能量可用性、肌肉功能、恢复与适应影响表现。')],[nb('Adrenaline from the adrenal glands increases heart rate, breathing, blood redistribution and glucose mobilisation.','肾上腺分泌的肾上腺素提高心率、呼吸、血流重新分配和葡萄糖动员。'),nb('Testosterone supports muscle protein synthesis, strength and power.','睾酮支持肌肉蛋白质合成、力量和功率。'),nb('Growth hormone supports growth and tissue repair; cortisol increases available glucose but can contribute to protein breakdown when its effect is prolonged.','生长激素支持生长和组织修复；皮质醇提高可用葡萄糖，但长期作用可能促进蛋白质分解。')],[],[],[nb('During a 100 m sprint, the CNS rapidly recruits motor units while adrenaline supports cardiovascular activation. During strength training, recruitment and training adaptations can increase force; during recovery, growth hormone and nutrition support repair.','100米冲刺中，中枢快速募集运动单位，肾上腺素支持心血管激活；力量训练中，募集和训练适应可增加力量；恢复期，生长激素和营养支持修复。')],[nb('Name two hormones and connect each to a performance or recovery role.','指出两种激素，并分别联系其表现或恢复作用。')],[nb('How do nervous and endocrine systems cooperate during a weightlifting event?','力量举过程中，神经和内分泌系统如何合作？')])
],examFocus:[nb('Separate rapid neural control from slower hormonal modulation in explanations.','在解释中区分快速神经控制与较慢的激素调节。')],quickCheck:[nb('Give one sporting example where both systems are active.','举出一个两种系统同时参与的运动例子。')]},
{code:'A.2.1',page:4,theme:'A',title:nb('Water and electrolyte balance','水与电解质平衡'),guidingQuestion:nb('How do water and electrolytes maintain health and support performance?','水和电解质如何维持健康并支持表现？'),intro:nb('Water and electrolytes are needed for thermoregulation, circulation, metabolism, nerve impulses, muscle contraction and joint function. Fluid balance depends on matching intake with losses from sweat, urine, respiration and faeces.','水与电解质支持体温调节、循环、代谢、神经冲动、肌肉收缩和关节功能。体液平衡取决于摄入与汗液、尿液、呼吸和粪便损失的匹配。'),sections:[
ns('Functions, intake and loss',[nb('Total body water is about 60% of adult body mass. Water regulates temperature through sweating, transports nutrients and wastes, lubricates tissues, supports blood volume and pressure, and enables chemical reactions.','成年人体内水分约占体重的60%。水通过出汗调节体温，运输营养和废物，润滑组织，支持血容量和血压，并使化学反应得以进行。')],[nb('Electrolytes include sodium, potassium and chloride. Sodium supports fluid balance and nerve function; potassium supports muscle contraction and heart rhythm; chloride supports fluid and acid-base balance.','电解质包括钠、钾和氯。钠支持体液平衡和神经功能；钾支持肌肉收缩和心律；氯支持体液和酸碱平衡。')],[nb('Dehydration','脱水', 'Body-water deficit that can increase heart rate, core temperature, fatigue and heat-illness risk.','身体缺水，可增加心率、核心体温、疲劳和热病风险。'),nb('Osmolality','渗透压', 'Concentration of dissolved particles in a solution.','溶液中溶解粒子的浓度。')],[],[nb('Exercise in heat can increase sweat loss to about 0.5–2.0 litres per hour and sodium loss to about 300–1000 mg per hour.','高温运动可使汗液损失增加到约每小时0.5–2.0升，钠损失约每小时300–1000毫克。')],[nb('Explain why fluid replacement must match sweat losses in hot endurance exercise.','解释为什么高温耐力运动中的补液必须与汗液损失相匹配。')],[nb('Name the main routes of fluid intake and loss.','说出液体摄入和损失的主要途径。')])
,ns('Imbalance and hydration monitoring',[nb('Dehydration is a water deficit. Hypernatremia is high blood sodium, often associated with excessive sweating and inadequate water replacement. Hyponatremia is low blood sodium and can follow excessive fluid intake or prolonged sweating without adequate sodium replacement.','脱水是水分不足。高钠血症是血钠过高，常与过度出汗和补水不足有关。低钠血症是血钠过低，可由过量饮水或长时间出汗而未充分补钠引起。')],[nb('Use several indicators rather than urine colour alone: body-mass change, urine colour and urine osmolality give complementary evidence.','应结合体重变化、尿色和尿液渗透压，不要只看尿色。'),nb('The workbook guideline is to avoid losing more than 2% of body mass during exercise.','工作册给出的指导是运动中体重下降不要超过2%。')],[],[],[nb('A runner loses body mass in a hot race and has concentrated urine. Explain the pattern without claiming that one indicator is sufficient.','跑者在高温比赛中体重下降且尿液浓缩。解释这一模式，但不要声称单一指标足够。')],[nb('Classify dehydration, hypernatremia and hyponatremia by cause and effect.','按原因和影响对脱水、高钠血症和低钠血症进行分类。')],[nb('Why are multiple hydration measures needed?','为什么需要多种水合指标？')])
,ns('ADH and cardiovascular drift',[nb('When plasma osmolality rises or blood volume falls, hypothalamic osmoreceptors promote ADH release from the posterior pituitary. ADH increases water reabsorption in kidney collecting ducts, producing less dilute urine and helping restore balance.','当血浆渗透压升高或血容量下降时，下丘脑渗透压感受器促进垂体后叶释放抗利尿激素。抗利尿激素增加肾集合管水分重吸收，使尿液更浓缩并帮助恢复平衡。')],[nb('In prolonged exercise in heat, dehydration reduces plasma volume and more blood is directed to the skin for cooling. Stroke volume can fall, so heart rate rises at the same workload; this is cardiovascular drift.','高温长时间运动中，脱水减少血浆容量，更多血液流向皮肤散热。每搏输出量可能下降，因此相同负荷下心率上升，这就是中心血管漂移。')],[nb('Negative feedback','负反馈', 'ADH release rises with the disturbance, water retention restores the variable, and the response then decreases.','扰动增加时抗利尿激素释放上升，水分保留恢复变量，随后反应减弱。')],[],[nb('Plan an endurance session in heat: start hydrated, drink regularly, replace sodium, monitor body mass and adjust the plan.','规划高温耐力训练：开始时水合、规律饮水、补充钠、监测体重并调整方案。')],[nb('Explain the feedback link between osmolality, ADH, kidney water reabsorption and urine concentration.','解释渗透压、抗利尿激素、肾水分重吸收和尿液浓度之间的反馈联系。')],[nb('What causes cardiovascular drift and how can it be reduced?','中心血管漂移的原因是什么？如何减轻？')])
],examFocus:[nb('Link hydration to thermoregulation, blood volume, nerve and muscle function; avoid detailed nephron structure.','将水合与体温调节、血容量、神经和肌肉功能联系起来；不需要 nephron 的细节。')],quickCheck:[nb('How does ADH help maintain fluid balance?','抗利尿激素如何帮助维持体液平衡？')]},
{code:'A.2.2',page:5,theme:'A',title:nb('Fuelling for health and performance','健康与表现供能'),guidingQuestion:nb('How can nutrition support health, exercise and recovery?','营养如何支持健康、运动和恢复？'),intro:nb('Carbohydrate, protein and lipid have different roles, but all three are needed in suitable amounts. Fuelling should match the activity, duration, environment, body composition, age, sex differences and gastrointestinal tolerance.','碳水化合物、蛋白质和脂质作用不同，但三者都需要适量。供能应匹配活动、时长、环境、身体组成、年龄、性别差异和胃肠耐受。'),sections:[
ns('Macronutrients and individual needs',[nb('Carbohydrate is the main fuel for high-intensity exercise, spares protein, supports immune function and replenishes muscle glycogen. Protein builds and repairs muscle and tissues and supplies enzymes, hormones and transport proteins. Lipid provides concentrated energy, supports hormones and organ protection, and helps absorb vitamins A, D, E and K.','碳水化合物是高强度运动的主要燃料，可节省蛋白质、支持免疫功能并补充肌糖原。蛋白质构建和修复肌肉及组织，并提供酶、激素和运输蛋白。脂质提供集中能量，支持激素和器官保护，并帮助吸收维生素A、D、E、K。')],[nb('Children and adolescents need energy, protein, calcium and iron for growth and development.','儿童和青少年需要能量、蛋白质、钙和铁以支持生长发育。'),nb('Menstruation increases iron requirements; energy and protein needs also vary with body size, lean mass, age and activity.','月经会增加铁需求；能量和蛋白质需求也随体型、瘦体重、年龄和活动量变化。'),nb('Higher physical activity generally increases energy, carbohydrate and fluid needs.','更高的身体活动量通常会提高能量、碳水和液体需求。')],[nb('Energy availability','能量可用性', 'The energy available to support health and training after exercise expenditure is accounted for.','扣除运动消耗后，可用于健康和训练的能量。')],[],[nb('An endurance athlete needs adequate carbohydrate before and during a long event, plus protein and fluids for recovery and tissue repair.','耐力运动员在长时间项目前后需要充足碳水，恢复和组织修复还需要蛋白质与液体。')],[nb('Justify a fuelling plan for a two-hour road race in warm conditions.','为高温两小时公路赛设计供能方案并说明理由。')],[nb('State one role of carbohydrate, protein and lipid.','分别说出碳水化合物、蛋白质和脂质的一项作用。')])
,ns('Pre-exercise, during-exercise and recovery',[nb('Pre-exercise food should generally be eaten 1–4 hours before activity, with carbohydrate and some protein, low fat and fibre, plus hydration. During exercise longer than 60 minutes or at high intensity, the workbook recommends about 30–60 g carbohydrate per hour and regular fluid intake.','运动前通常应在1–4小时进食，以碳水和适量蛋白质为主，减少脂肪和纤维并充分水合。运动超过60分钟或强度较高时，工作册建议每小时约30–60克碳水，并规律补液。')],[nb('Practise fuelling in training so the gut becomes familiar with the food and timing.','在训练中练习供能，让胃肠适应食物和时间安排。'),nb('Sodium may be considered for prolonged or heavy-sweat sessions; replacement must match sweat losses and conditions.','长时间或大量出汗的运动可考虑补钠，补充量应与汗液损失和条件相匹配。')],[nb('Low energy availability','低能量可用性', 'Insufficient energy for health and daily function after exercise energy expenditure.','运动消耗后，能量不足以支持健康和日常功能。'),nb('RED-S','RED-S', 'Relative energy deficiency in sport, a health and performance problem linked to low energy availability.','运动中的相对能量缺乏，与低能量可用性相关的健康和表现问题。')],[],[nb('A cyclist might use a familiar pre-ride meal, a drink or gel during the ride, and carbohydrate, protein and fluid after finishing.','骑行者可以在骑行前吃熟悉的餐食，骑行中饮用运动饮料或能量胶，完成后补充碳水、蛋白质和液体。')],[nb('Explain why there is no universal meal plan.','解释为什么不存在适用于所有人的餐单。')],[nb('How much carbohydrate per hour is suggested during exercise?','运动中建议每小时摄入多少碳水？')])
,ns('Micronutrients, RED-S and microbiome',[nb('Iron supports haemoglobin and oxygen transport; calcium supports strong bones and teeth; sodium supports fluid balance, blood volume, nerves and muscle; potassium supports fluid balance, nerve and muscle function. Vitamins support immunity and energy release, with D and K especially relevant to bone health.','铁支持血红蛋白和氧气运输；钙支持强健骨骼和牙齿；钠支持体液平衡、血容量、神经和肌肉；钾支持体液平衡以及神经和肌肉功能。维生素支持免疫和能量释放，其中D和K与骨骼健康尤其相关。'),nb('Low energy availability can affect metabolism, menstrual function, bone mineral density, immunity, growth, cardiovascular and psychological health, recovery and performance.','低能量可用性可影响代谢、月经功能、骨矿物质密度、免疫、生长、心血管和心理健康、恢复及表现。')],[nb('Gut microbiome','肠道微生物组', 'Microbial communities in the gut influenced by genetics, diet, medication, sleep, stress and activity.','肠道中的微生物群，受到遗传、饮食、药物、睡眠、压力和活动影响。'),nb('Relative energy deficiency in sport','运动中的相对能量缺乏', 'A condition associated with low energy availability and effects across health and performance.','与低能量可用性相关，并影响健康和表现。')],[],[nb('Iron may be especially important for adolescent and female athletes; calcium and potassium can be obtained through a varied diet.','铁对青少年和女性运动员尤其重要；钙和钾可通过多样化饮食获得。')],[nb('Define RED-S and name two possible consequences.','定义RED-S并说出两个可能后果。')],[nb('Name two key sources of iron and calcium.','指出铁和钙的两个主要来源。')])
],examFocus:[nb('Use individualisation, gastrointestinal comfort and RED-S rather than prescribing one universal diet.','使用个体化、胃肠舒适和RED-S，而不是开出统一饮食处方。')],quickCheck:[nb('What factors influence nutrition needs?','哪些因素会影响营养需求？'),nb('How can good nutrition enhance performance and recovery?','良好营养如何提升表现和恢复？')]},
{code:'A.2.3',page:6,theme:'A',title:nb('Energy systems','能量系统'),guidingQuestion:nb('How do energy systems supply ATP for physical activity?','能量系统如何为身体活动供应ATP？'),intro:nb('ATP is the immediate energy currency for contraction, ion pumping, biosynthesis and nerve impulses. The phosphagen, glycolytic and oxidative systems resynthesise ATP continuously; their contribution changes with intensity and duration.','ATP是肌肉收缩、离子泵、合成和神经冲动的即时能量货币。磷酸原、糖酵解和氧化系统持续再合成ATP；它们的贡献随强度和持续时间变化。'),sections:[
ns('ATP and the energy continuum',[nb('ATP releases energy when it is hydrolysed to ADP and phosphate. The energy systems differ in oxygen requirement, fuel, ATP supply, power, duration, fatigue and recovery, but they overlap rather than switch on and off.','ATP水解为ADP和无机磷酸时释放能量。三个系统在氧气需求、燃料、ATP供应、功率、持续时间、疲劳和恢复方面不同，但它们相互重叠而不是彼此完全开关。')],[nb('All three systems contribute at every intensity; the dominant contribution shifts along the energy continuum.','在任何强度下三个系统都会贡献ATP，只是主导贡献沿能量连续体改变。')],[nb('ATP','三磷酸腺苷', 'Immediate energy currency used by cellular work.','细胞工作的即时能量货币。'),nb('Lactate','乳酸盐', 'A product associated with glycolytic metabolism and fatigue context.','与糖酵解代谢及疲劳情境相关的产物。')],[],[nb('A 100 m sprint is dominated by phosphagen contribution, a 400 m sprint gains glycolytic contribution, and a 10 km run relies more on oxidative resynthesis.','100米冲刺主要依赖磷酸原，400米冲刺增加糖酵解贡献，10公里跑更多依赖氧化再合成。')],[nb('Match a 100 m sprint, 400 m sprint and 10 km run to dominant ATP supply.','将100米、400米和10公里跑步匹配到主要ATP供应。')],[nb('Why is it inaccurate to say that only one energy system works in a sport?','为什么说运动中只有一个能量系统在工作是错误的？')])
,ns('Comparing the three systems',[nb('The phosphagen system uses ATP and phosphocreatine without oxygen, produces very high power for a small amount of ATP and fatigues quickly. The glycolytic system uses carbohydrate without oxygen, supplies moderate ATP at high intensity for roughly 30 seconds to 2 minutes, and produces lactate and hydrogen ions. The oxidative system requires oxygen, uses carbohydrate, fat and some protein, supplies a large amount of ATP for minutes to hours, and supports endurance.','磷酸原系统利用ATP和磷酸肌酸且不需要氧气，功率很高但ATP储量小并很快疲劳。糖酵解系统无氧利用碳水化合物，在高强度下提供中等ATP供应，约持续30秒至2分钟，并产生乳酸和氢离子。氧化系统需要氧气，利用碳水、脂肪和少量蛋白质，在数分钟至数小时内提供大量ATP，支持耐力活动。')],[nb('Phosphagen is strongest for starts, jumps and throws.','磷酸原适合起跑、跳跃和投掷。'),nb('Glycolytic contribution is important for 200–400 m efforts, repeated sprints and HIIT.','糖酵解对200–400米、重复冲刺和高强度间歇训练很重要。'),nb('Oxidative contribution supports 1500 m, distance running, cycling and rowing.','氧化贡献支持1500米、长跑、骑行和划船。')],[],[],[nb('A 400 m runner gains power from anaerobic contribution but still receives aerobic support; pacing and training affect how long each system can contribute.','400米跑者从无氧贡献中获得功率，但仍得到有氧支持；配速和训练影响各系统能维持贡献的时间。')],[nb('Compare oxygen use, fuels, ATP supply, duration and recovery for the three systems.','比较三个系统的氧气使用、燃料、ATP供应、持续时间和恢复。')],[nb('Compare the three energy systems in a table.','用表格比较三个能量系统。')])
,ns('VO₂max, movement economy, LIP and EPOC',[nb('VO₂max is the maximum rate of oxygen uptake. Movement economy is the oxygen cost of a given submaximal speed; a more economical movement uses less oxygen for the same task. Lactate inflection point is the point at which blood lactate begins to rise above baseline. EPOC is the extra oxygen needed after exercise to restore the body, with a fast component in roughly the first two minutes and a slower component afterwards.','VO₂max是最大摄氧率。动作经济性是完成某个次最大速度所需的氧气；经济性越高，同一任务耗氧越少。乳酸拐点是血乳酸开始高于基线的点。EPOC是运动后恢复身体所需的额外氧气，约前两分钟为快成分，之后为慢成分。')],[nb('Intensity below the lactate inflection point is mostly aerobic; above it, anaerobic contribution increases.','低于乳酸拐点的强度主要为有氧；超过后无氧贡献增加。'),nb('EPOC supports restoration of oxygen stores, ATP-PCr, lactate clearance, tissue repair and thermoregulation.','EPOC帮助恢复氧储量、ATP-磷酸肌酸、清除乳酸、组织修复和体温调节。')],[nb('VO₂max','最大摄氧量', 'Maximum oxygen uptake capacity.','最大摄氧能力。'),nb('Movement economy','动作经济性', 'Oxygen cost of a given submaximal movement.','完成给定次最大动作的氧气成本。'),nb('EPOC','运动后氧耗', 'Extra oxygen used after exercise to restore physiological systems.','运动后恢复生理系统所需的额外氧气。')],[],[nb('An endurance athlete can improve aerobic capacity and movement economy, while intervals or tempo work can target intensity around the lactate inflection point.','耐力运动员可以提高有氧能力和动作经济性；间歇或节奏训练可针对乳酸拐点附近的强度。')],[nb('Define VO₂max, movement economy, LIP and EPOC.','定义VO₂max、动作经济性、LIP和EPOC。')],[nb('Give one training implication for VO₂max and one for EPOC.','分别为VO₂max和EPOC写出一个训练启示。')])
],examFocus:[nb('Use the energy continuum and sport examples rather than detailed Krebs-cycle or enzyme pathways.','使用能量连续体和运动例子，而不是详细Krebs循环或酶通路。')],quickCheck:[nb('How do the energy systems work together?','能量系统如何协同工作？')]},
{code:'A.3.1',page:7,theme:'A',title:nb('Qualities of training','训练品质'),guidingQuestion:nb('How should training be planned to improve performance safely?','训练应如何规划才能安全提高表现？'),intro:nb('Effective training is specific, progressively overloaded, varied, recoverable and planned across time. The athlete’s current fitness, goal, phase, health and response to load must guide FITT choices and monitoring.','有效训练应具备专项性、渐进超负荷、多样性、恢复和时间规划。运动员当前水平、目标、训练阶段、健康状况和负荷反应应指导FITT选择与监测。'),sections:[
ns('Six qualities and FITT',[nb('Specificity means training the sport, position and goal. Progressive overload means gradually increasing training stress. Recovery or rest allows repair and adaptation. Variety maintains motivation and reduces plateaus. Reversibility means fitness is lost when training stops. Periodization organises training in cycles to peak at the right time.','专项性要求训练与项目、位置和目标相匹配。渐进超负荷逐步增加训练压力。恢复或休息使身体修复和适应。多样性维持动力并减少平台期。可逆性表示停止训练后体能会下降。周期化用不同训练周期在合适时间达到高峰。')],[nb('FITT: frequency is how often, intensity is how hard, time is how long and type is what method.','FITT：频率是训练多频繁，强度是多努力，时间是训练多久，类型是采用什么方法。'),nb('Progressive overload should be gradual, monitored and compatible with recovery.','渐进超负荷应是渐进的、受监测的，并与恢复相容。')],[nb('Periodization','周期化', 'Planning training in macro-, meso- and microcycles.','以大周期、中周期和小周期规划训练。'),nb('Reversibility','可逆性', 'The loss of fitness when training stops or decreases.','训练停止或减少时体能下降。')],[],[nb('An 800 m runner uses race-specific work, suitable volume and pace, regular recovery and monitoring of split times or heart-rate response.','800米跑者采用专项比赛训练、合适训练量和配速，规律恢复，并监测分段成绩或心率反应。')],[nb('Turn a performance goal into FITT choices and a monitoring measure.','把表现目标转化为FITT选择和监测指标。')],[nb('Define specificity, progressive overload, recovery, variety, reversibility and periodization.','定义专项性、渐进超负荷、恢复、多样性、可逆性和周期化。')])
,ns('Periodization, overload and overtraining',[nb('A macrocycle is a long-term season or year plan, a mesocycle is a phase or block of several weeks, and a microcycle is a week containing daily training. Preparation builds fitness and skills, competition performs and peaks, and transition provides active rest and recovery.','大周期是赛季或年度长期计划，中周期是数周的运动阶段或训练块，小周期是包含每日训练的7天周期。准备期发展体能和技能，比赛期表现并达到高峰，过渡期提供主动休息和恢复。')],[nb('Functional overreaching is a planned short-term increase in load with temporary performance loss, followed by recovery and possible supercompensation.','功能性过训练反应是计划内短期增加负荷，表现暂时下降，随后恢复并可能出现超量恢复。'),nb('Overtraining is an excessive load sustained too long, with persistent decline, chronic fatigue, poor sleep, mood disturbance and higher illness or injury risk.','过度训练是负荷长期过高，表现持续下降、慢性疲劳、睡眠不佳、情绪问题以及疾病或受伤风险增加。')],[nb('Macrocycle','大周期', 'Long-term plan, usually a season or year.','长期计划，通常是赛季或年度。'),nb('Microcycle','小周期', 'Short-term plan, usually one week.','短期计划，通常是一周。')],[],[nb('A coach increases load for one block, schedules recovery and checks whether performance returns; persistent fatigue would prompt a load review.','教练在一个训练块增加负荷，安排恢复并检查表现是否恢复；持续疲劳会促使重新审视负荷。')],[nb('Distinguish functional overreaching from overtraining.','区分功能性过训练反应与过度训练。')],[nb('How can monitoring reduce the risk of overtraining?','监测如何降低过度训练风险？')])
,ns('Individualisation and the monitoring loop',[nb('Training should respond to current fitness, age, sex-related factors, menstrual-cycle changes where relevant, genetics and responder differences, plus the current macrocycle phase. Baseline testing, regular monitoring, analysis, adjustment and review create a feedback loop.','训练应考虑当前水平、年龄、性别相关因素、相关的月经周期变化、遗传与反应差异，以及当前大周期阶段。基线测试、定期监测、分析、调整和复查形成反馈循环。')],[nb('Training data include load, volume, intensity and RPE; wellbeing includes sleep, mood, stress and motivation; performance tests should include relevant sport-specific measures.','训练数据包括负荷、训练量、强度和主观用力程度；健康状态包括睡眠、情绪、压力和动机；表现测试应包含相关专项指标。')],[nb('Responder','反应者', 'An individual whose response to a training stimulus differs from another person’s.','对训练刺激的反应因人而异的人。')],[],[nb('Monitor one athlete’s training response, adjust one FITT variable and set a new review point rather than applying a universal programme.','监测一名运动员的训练反应，调整一个FITT变量，并设置新的复查点，而不是套用统一计划。')],[nb('Explain why training must be individualised.','解释为什么训练必须个体化。')],[nb('What are the stages of a useful monitoring loop?','有用监测循环的阶段是什么？')])
],examFocus:[nb('Apply the qualities to FITT, periodization and monitoring; do not memorise exact load percentages or full programmes.','把训练品质应用到FITT、周期化和监测；不需要记忆精确负荷百分比或完整计划。')],quickCheck:[nb('Why is recovery essential to progressive overload?','为什么恢复对渐进超负荷至关重要？')]},
{code:'A.3.2',page:8,theme:'A',title:nb('Benefits to health of being active','身体活动的健康益处'),guidingQuestion:nb('How does physical activity influence health across different populations?','身体活动如何影响不同人群的健康？'),intro:nb('Regular activity supports muscular, skeletal, immune, cardiovascular and mental health, and lowers the risk of several non-communicable diseases. Benefits depend on age, starting level, sex differences, progression, health status and whether the activity is appropriate.','规律活动支持肌肉、骨骼、免疫、心血管和心理健康，并降低多种非传染性疾病风险。益处取决于年龄、起始水平、性别差异、渐进过程、健康状态以及活动是否合适。'),sections:[
ns('Life stage, sex and energy balance',[nb('Children build fundamental movement skills and support growth. Adolescents improve fitness, body composition and well-being. Adults maintain function, and older adults benefit from reduced frailty and maintained independence.','儿童建立基本动作技能并支持生长；青少年改善体能、身体组成和幸福感；成人维持功能；老年人减少虚弱并维持独立性。')],[nb('Energy intake is compared with expenditure from basal metabolism, physical activity and the thermic effect of food. A deficit can reduce weight; balance supports stable weight and function; a surplus stores energy.','能量摄入要与基础代谢、身体活动和食物热效应产生的消耗比较。赤字可减重；平衡有助于体重稳定和功能；过剩会储存能量。'),nb('Females may have a higher risk of iron deficiency, and hormonal cycles can affect energy and performance.','女性缺铁风险可能更高，激素周期可影响能量和表现。')],[nb('Energy balance','能量平衡', 'The relationship between energy intake and energy expenditure.','能量摄入与能量消耗之间的关系。')],[],[nb('A programme should start from a person’s current activity level and progress according to health, age, ability and response.','训练计划应从个人当前活动水平开始，并按健康、年龄、能力和反应逐步进阶。')],[nb('Why should activity recommendations consider age and sex differences?','活动建议为何要考虑年龄和性别差异？')],[nb('Explain energy balance and one possible outcome.','解释能量平衡及一个可能结果。')])
,ns('System benefits, chronic disease and progression',[nb('Physical activity can increase muscular strength and endurance, improve bone density, support immune function, reduce stress and anxiety, improve mood and sleep, and increase confidence and resilience. Poor progression or excessive activity can instead cause overuse injury, soreness, fatigue, suppressed immune function, stress or burnout.','身体活动可以增强肌力和耐力、提高骨密度、支持免疫、减轻压力和焦虑、改善情绪和睡眠，并增强自信与韧性。进展不当或活动过量也可能导致过度使用性损伤、酸痛、疲劳、免疫受抑、压力或倦怠。')],[nb('Regular activity can reduce risk of osteoporosis, obesity, hypertension, cardiovascular disease and type 2 diabetes.','规律活动可降低骨质疏松、肥胖、高血压、心血管疾病和2型糖尿病风险。')],[nb('Progressive intensity','渐进强度', 'Gradual increase in workload with recovery, monitoring and avoidance of sudden large changes.','在恢复、监测和避免突然大幅增加的前提下逐步提高负荷。')],[],[nb('For an older adult returning after inactivity, begin with appropriate work, progress gradually, include strength and balance, and modify for health and injury risk.','久坐老年人恢复活动时，应从适当工作量开始，逐步进阶，加入力量和平衡，并按健康及受伤风险调整。')],[nb('Prescribe a progression for a population and justify one safety modification.','为某人群设计进阶并说明一项安全调整。')],[nb('Name two positive and two negative effects of activity if overdone.','指出活动适量时的两个正面效果和过量时的两个负面效果。')])
,ns('HL exercise prescription for populations',[nb('The workbook gives population-focused guidance. Children and adolescents need moderate-to-vigorous activity, variety, fun and skill development. Older adults need moderate aerobic activity plus balance, muscle and bone-strengthening work to support independence. Pregnant individuals can use moderate activity, including pelvic-floor and flexibility work, with hydration and adjustment by trimester.','工作册给出针对人群的建议。儿童青少年需要中高强度活动、多样性、趣味和技能发展；老年人需要中等强度有氧活动以及平衡、肌肉和骨骼强化训练以维持独立；孕期人群可进行中等强度活动，包括盆底和柔韧练习，并按孕期补水与调整。')],[nb('Prescription must be individualised and adjusted as needs change.','运动处方必须个体化，并随需求变化调整。')],[nb('Safety modification','安全调整', 'A change to activity or environment that lowers risk for a person or population.','为个人或人群降低风险而对活动或环境作出的调整。')],[],[nb('For pregnancy, progress gently, avoid overheating, maintain hydration and seek professional advice when the individual’s history requires it.','孕期应温和渐进、避免过热、保持水合；个人病史需要时应寻求专业建议。')],[nb('How should exercise prescription differ for children, older adults and pregnancy?','儿童、老年人和孕期运动处方应有何不同？')],[nb('Name two chronic-disease risks reduced by regular activity.','说出规律活动可降低的两种慢性病风险。')])
],examFocus:[nb('Justify benefits and safety modifications for a population without overlearning bone-cell pathways.','为某人群论证益处和安全调整，不需要过度学习骨细胞通路。')],quickCheck:[nb('Why is progressive overload important for health?','渐进超负荷为何对健康重要？')]},
{code:'A.3.3',page:9,theme:'A',title:nb('Fatigue and recovery','疲劳与恢复'),guidingQuestion:nb('Why does fatigue develop and how can recovery be supported?','疲劳为何产生，恢复如何得到支持？'),intro:nb('Fatigue can be central, arising from reduced brain drive or motivation, or peripheral, arising in muscle or at the neuromuscular junction. Recovery is multidimensional: physiological, symptom-based, psychological and practical indicators should be monitored together.','疲劳可分为中枢性疲劳，即脑部驱动或动机下降，以及外周性疲劳，即肌肉或神经肌肉接点的问题。恢复是多维度的，应同时监测生理、症状、心理和实际指标。'),sections:[
ns('Central and peripheral fatigue',[nb('Central fatigue includes reduced drive from the brain, decreased motivation and greater perception of effort. Peripheral fatigue includes metabolic by-products, potassium changes, low glycogen, hydration and sodium changes, calcium handling and impaired excitation-contraction coupling.','中枢性疲劳包括脑部驱动减少、动机下降和用力感增加。外周性疲劳涉及代谢产物、钾变化、糖原不足、脱水和钠变化、钙处理以及兴奋-收缩耦联受损。')],[nb('Both central and peripheral factors can interact and limit performance.','中枢和外周因素可能相互作用并限制表现。'),nb('Recovery is not judged only by feeling less tired.','恢复不能只用“感觉不累”来判断。')],[nb('Central fatigue','中枢性疲劳', 'Reduced central drive, motivation or perceived effort.','中枢驱动、动机或用力感下降。'),nb('Peripheral fatigue','外周性疲劳', 'Fatigue arising in muscle or at the neuromuscular junction.','发生在肌肉或神经肌肉接点的疲劳。')],[],[nb('After a hard session, an athlete may feel motivated but still have low glycogen, fluid loss or impaired ion handling, so subjective freshness is insufficient.','高强度训练后，运动员可能感觉有动力，但糖原低、体液流失或离子处理受损，因此主观精神好并不足够。')],[nb('Distinguish central from peripheral fatigue.','区分中枢性与外周性疲劳。')],[nb('Give three peripheral contributors and their effects.','给出三个外周因素及其影响。')])
,ns('Recovery nutrition and methods',[nb('Carbohydrate replenishes muscle glycogen, protein provides amino acids for repair and adaptation, water rehydrates, and creatine monohydrate restores phosphocreatine stores. Polyphenol-rich foods, myofascial release, compression garments, thermotherapy, sleep and travel management may support perceived recovery when used appropriately.','碳水化合物补充肌糖原，蛋白质提供修复和适应所需的氨基酸，水负责再水合，肌酸一水合物恢复磷酸肌酸储存。多酚食物、筋膜放松、压缩衣、温热疗法、睡眠和旅行管理可在适当情况下帮助恢复感。')],[nb('The recovery timeline is 0–30 minutes to refuel and rehydrate, 30–120 minutes to repair and restock, 2–4 hours to restore and refuel, and daily nutrition to support adaptation.','恢复时间线：0–30分钟补充能量和水分，30–120分钟修复和补充，2–4小时恢复和补充，之后依靠每日营养支持适应。')],[nb('Recovery indicator','恢复指标', 'A physiological, symptom, psychological or practical sign used to judge readiness.','用于判断准备状态的生理、症状、心理或实际迹象。')],[],[nb('After a long race, prioritise carbohydrate, protein and fluid, then use sleep and practical routines to support the next session.','长距离比赛后优先补充碳水、蛋白质和液体，再通过睡眠和实际安排支持下一次训练。')],[nb('Evaluate recovery with more than one indicator.','用不止一个指标评估恢复。')],[nb('Name three key recovery nutrients and their roles.','说出三种关键恢复营养素及其作用。')])
,ns('Recovery indicators, sleep and travel',[nb('Physiological indicators include resting heart rate returning toward baseline, improved heart-rate variability, less soreness, reduced inflammatory markers and better sleep. Symptomatic indicators include lower fatigue, less pain or stiffness, better function, lower RPE and improved appetite. Psychological indicators include better mood, confidence, concentration and motivation to train.','生理指标包括静息心率回归基线、心率变异性改善、酸痛减少、炎症标志物下降和睡眠改善。症状指标包括疲劳、疼痛或僵硬减少，功能和食欲改善，主观用力感降低。心理指标包括情绪、自信、注意力和训练动机改善。'),nb('High training load can accumulate fatigue, disrupt hormones, impair sleep and reduce performance. Travel and time-zone changes can cause circadian misalignment, poor sleep, fatigue, reduced performance, gastrointestinal upset and dehydration.','高训练负荷会积累疲劳、扰乱激素、损害睡眠并降低表现。旅行和时区变化可造成昼夜节律错位、睡眠差、疲劳、表现下降、胃肠不适和脱水。')],[nb('Heart-rate variability','心率变异性', 'Variation between heartbeats used in the workbook as a recovery-related indicator.','心跳间隔变化，工作册将其作为恢复相关指标。'),nb('Circadian rhythm','昼夜节律', 'The daily timing pattern affected by light, sleep and travel.','受光照、睡眠和旅行影响的每日时间模式。')],[],[nb('A pre-competition plan should use sleep, light exposure, hydration, nutrition and light mobility to reduce travel disruption.','赛前计划应使用睡眠、光照暴露、补液、营养和轻度活动来减少旅行干扰。')],[nb('How do sleep and travel disruption affect recovery?','睡眠和旅行干扰如何影响恢复？')],[nb('Name three physiological indicators of recovery.','说出三个恢复的生理指标。')])
],examFocus:[nb('Evaluate readiness using several domains and connect recovery choices to the goal, timing and athlete.','用多个领域评估准备状态，并将恢复选择与目标、时机和运动员联系起来。')],quickCheck:[nb('Choose one physiological, one psychological and one practical recovery indicator.','各选一个生理、心理和实际恢复指标。')]},
{code:'B.1.1',page:10,theme:'B',title:nb('Anatomical position, planes and movement','解剖位置、平面与运动'),guidingQuestion:nb('How can precise anatomical language describe human movement?','精确的解剖语言如何描述人体运动？'),intro:nb('Anatomical position is the standard reference position. Planes divide the body, axes run perpendicular to planes, and movement terms describe actions at joints. Precise language supports analysis, coaching, equipment design and injury prevention.','解剖位置是标准参考位置。平面分割身体，轴与平面垂直，运动术语描述关节处的动作。精确语言支持动作分析、教练、装备设计和损伤预防。'),sections:[
ns('Skeleton, position and directional terms',[nb('The axial skeleton includes the skull, vertebral column, rib cage and sternum; it protects vital organs. The appendicular skeleton includes the shoulder and pelvic girdles and the upper and lower limbs; it enables movement.','轴向骨骼包括颅骨、脊柱、胸廓和胸骨，保护重要器官；附肢骨骼包括肩带、骨盆带和上下肢，支持运动。')],[nb('Anatomical position: standing upright and facing forward, head level, eyes forward, arms at the sides with palms forward, feet flat and toes forward.','解剖位置：直立并面向前方，头部水平、眼睛向前、手臂位于身体两侧且掌心向前、双脚平放、脚尖向前。'),nb('Superior/inferior describe above/below; medial/lateral describe toward/away from the midline; proximal/distal describe nearer/farther from the point of origin; anterior/posterior describe front/back.','上/下表示更靠头部/足部；内/外表示靠近/远离中线；近端/远端表示距离起源较近/较远；前/后表示身体前面/后面。')],[nb('Anatomical position','解剖位置', 'The standard reference standing position used to describe the body.','描述身体的标准站立参考位置。')],[],[nb('“The sole turns inward” is inversion; “the sole turns outward” is eversion. Explain each using directional terms.','“脚底向内”是内翻；“脚底向外”是外翻。用方向术语解释。')],[nb('Name the plane, axis and movement terms for a squat or biceps curl.','为深蹲或弯举说出平面、轴和运动术语。')],[nb('Define proximal and distal.','定义近端和远端。')])
,ns('Planes, axes and movement',[nb('A sagittal plane divides left and right and has a transverse or mediolateral axis; movement examples include flexion and extension. A frontal or coronal plane divides front and back and has an anteroposterior axis; examples include abduction, adduction and lateral flexion. A transverse or horizontal plane divides top and bottom and has a longitudinal or vertical axis; examples include rotation.','矢状面将身体分为左右，绕横轴或内外侧轴运动，例如屈曲和伸展；额状面将身体分为前后，绕前后轴运动，例如外展、内收和侧屈；水平面将身体分为上下，绕纵轴或垂直轴运动，例如旋转。')],[nb('Joint movement depends on the joint surface, axis and muscles crossing the joint.','关节运动取决于关节面、轴以及跨关节的肌肉。')],[nb('Flexion','屈曲', 'Decrease the angle at a joint.','关节角度减小。'),nb('Extension','伸展', 'Increase the angle at a joint.','关节角度增大。'),nb('Abduction','外展', 'Move away from the midline.','远离中线移动。'),nb('Adduction','内收', 'Move towards the midline.','向中线移动。')],[],[nb('During elbow flexion in a biceps curl, the movement occurs in the sagittal plane around a mediolateral axis.','弯举中肘屈曲发生在矢状面，并绕内外侧轴运动。')],[nb('Compare the three planes and their perpendicular axes.','比较三个平面及其垂直轴。')],[nb('Give a movement example for each plane.','为每个平面给出一个运动例子。')])
,ns('HL anthropometry and ergonomics',[nb('Anthropometry measures body dimensions such as stature, sitting height, arm span, limb lengths, shoulder width, hip width, hand span and foot length. Equipment sizing uses these data to improve fit, comfort, safety and performance. Ergonomics designs tasks, tools and environments to reduce strain, improve efficiency and support neutral alignment.','人体测量测量身高、坐高、臂展、肢长、肩宽、髋宽、手跨和足长等身体尺寸。装备设计利用这些数据改善贴合、舒适、安全和表现。人体工程学通过任务、工具和环境设计减少应力、提高效率并支持中立排列。')],[nb('Cycling seat, handlebar and pedal positions can affect power and strain.','自行车的座椅、车把和踏板位置会影响功率与应力。'),nb('Appropriate footwear, helmet, racket or rowing-seat fit can improve control and reduce risk.','合适的鞋、头盔、球拍或划船座椅定位可改善控制并降低风险。')],[nb('Anthropometry','人体测量', 'Measurement of body dimensions used for design and equipment sizing.','用于设计和装备尺寸选择的身体尺寸测量。'),nb('Ergonomics','人体工程学', 'Design of tasks, equipment and environments for efficiency and reduced risk.','为提高效率、降低风险而设计任务、装备和环境。')],[],[nb('A taller athlete may need a longer frame or larger equipment, but the design must still allow control and safe movement.','较高的运动员可能需要更长的车架或更大的装备，但设计仍必须允许控制和安全运动。')],[nb('How can anthropometry influence equipment design?','人体测量如何影响装备设计？')],[nb('Give one ergonomic adjustment for a sport task.','为一个运动任务给出人体工程学调整。')])
],examFocus:[nb('Use precise plane, axis and movement terminology, and connect anthropometry or ergonomics to a real equipment decision.','使用精确的平面、轴和运动术语，并将人体测量或人体工程学联系到真实装备决策。')],quickCheck:[nb('How does ergonomics improve performance?','人体工程学如何提高表现？')]},
{code:'B.1.2',page:11,theme:'B',title:nb('Connective tissues and joints','结缔组织与关节'),guidingQuestion:nb('How do connective tissues and joint structures permit movement while maintaining stability?','结缔组织和关节结构如何在保持稳定的同时允许运动？'),intro:nb('Connective tissues form the framework that supports, links and transmits forces. Joints are classified by the tissue connecting the bones, and synovial joints combine cartilage, synovial fluid, capsule, ligaments and tendons to balance mobility with stability.','结缔组织形成支撑、连接和传递力量的框架。关节按连接骨的组织分类，滑膜关节结合软骨、滑液、关节囊、韧带和肌腱，在活动度与稳定性之间取得平衡。'),sections:[
ns('Connective tissues and articulations',[nb('Bone supports and protects, acts as a lever and stores minerals. Ligaments connect bone to bone, stabilise joints and limit excessive movement. Cartilage reduces friction and absorbs shock. Fascia wraps and separates structures. Tendon connects muscle to bone, transmits force and can store elastic energy.','骨支撑和保护、作为杠杆并储存矿物质；韧带连接骨与骨、稳定关节并限制过度运动；软骨减少摩擦并吸收冲击；筋膜包裹和分隔结构；肌腱连接肌肉与骨、传递力量并可储存弹性能。')],[nb('Fibrous joints are very stable and usually immovable, such as skull sutures. Cartilaginous joints allow slight movement and absorb shock, such as intervertebral discs. Synovial joints allow wide movement with low friction, such as knee and shoulder.','纤维关节非常稳定且通常不活动，如颅缝；软骨关节允许少量运动并吸收冲击，如椎间盘；滑膜关节以低摩擦提供广泛运动，如膝和肩。')],[nb('Ligament','韧带', 'Bone-to-bone tissue that stabilises a joint.','连接骨与骨、稳定关节的组织。'),nb('Synovial joint','滑膜关节', 'A freely movable joint with cartilage, synovial fluid, capsule and ligaments.','具有软骨、滑液、关节囊和韧带的自由活动关节。')],[],[nb('A wrist uses smaller gliding movements while a shoulder uses multiaxial movement. Use joint class to explain the difference.','手腕进行小范围滑动，肩关节进行多轴运动。用关节类别解释差异。')],[nb('Compare fibrous, cartilaginous and synovial joints.','比较纤维、软骨和滑膜关节。')],[nb('Name the function of a ligament and a tendon.','说出韧带和肌腱的功能。')])
,ns('Synovial structure and joint classes',[nb('Articular cartilage reduces friction and absorbs shock. Synovial membrane produces fluid, synovial fluid lubricates and nourishes cartilage and removes waste. The capsule encloses the joint, ligaments strengthen it, and tendons outside the capsule transmit muscle force.','关节软骨减少摩擦并吸收冲击；滑膜产生滑液，滑液润滑并滋养软骨、清除废物；关节囊包围关节，韧带加强稳定，囊外肌腱传递肌肉力量。')],[nb('Ball-and-socket joints are multiaxial; hinge joints are uniaxial; pivot joints allow rotation; condyloid joints are biaxial; saddle joints allow opposition; plane joints glide.','球窝关节多轴；铰链关节单轴；枢轴关节旋转；髁状关节双轴；鞍状关节允许对掌；平面关节滑动。')],[nb('Mobility','活动度', 'The range of movement available at a joint.','关节可提供的运动范围。'),nb('Stability','稳定性', 'The ability to resist unwanted movement and transfer force safely.','抵抗不必要运动并安全传递力量的能力。')],[],[nb('Shoulder mobility supports throwing, while knee stability and ligament control are important for cutting and landing.','肩部活动度支持投掷，膝关节稳定性和韧带控制对变向和落地很重要。')],[nb('How do synovial structures allow movement and stability together?','滑膜结构如何兼顾运动和稳定？')],[nb('Name three synovial joint classes and a sport example for each.','说出三个滑膜关节类别及各自运动例子。')])
,ns('Mobility, stability and injury',[nb('High mobility supports skill performance but can increase instability risk. High stability protects the joint and transfers force but can reduce movement efficiency. Optimal performance uses the appropriate balance for the task.','高活动度支持技能表现，但可能增加不稳定风险；高稳定性保护关节并传递力量，但可能降低运动效率。最佳表现取决于任务所需的适当平衡。')],[nb('Warm-up, strength, technique, recovery and appropriate equipment support joint health.','热身、力量、技术、恢复和合适装备支持关节健康。')],[nb('Ligament sprain or tear can produce instability and swelling; tendon problems can reduce force transfer; cartilage wear can cause pain, stiffness and reduced range of motion.','韧带扭伤或撕裂可导致不稳定和肿胀；肌腱问题可降低力量传递；软骨磨损可导致疼痛、僵硬和活动范围减少。')],[],[],[nb('Cutting, landing and change of direction require ligament control and adequate force absorption.','变向、落地和改变方向需要韧带控制和足够的冲击力吸收。')],[nb('Explain how joint structure supports performance and resists injury.','解释关节结构如何支持表现并抵抗损伤。')],[nb('Give one example of a connective-tissue or joint injury.','举出一个结缔组织或关节损伤例子。')])
],examFocus:[nb('Relate structure to function, then apply it to mobility, stability, performance and injury.')],quickCheck:[nb('Why is a synovial joint able to move smoothly?','滑膜关节为什么能平滑运动？')]},
{code:'B.1.3',page:12,theme:'B',title:nb('Muscular function','肌肉功能'),guidingQuestion:nb('How do motor units, fibre types and contractions create force and movement?','运动单位、肌纤维类型和收缩如何产生力量与运动？'),intro:nb('A motor unit is one motor neuron and all the fibres it stimulates. Recruitment, fibre type, contraction type and the sliding-filament mechanism explain how skeletal muscle produces and controls force.','运动单位是一个运动神经元及其刺激的所有肌纤维。募集、肌纤维类型、收缩类型和滑动肌丝机制解释了骨骼肌如何产生并控制力量。'),sections:[
ns('Motor units and fibre types',[nb('The all-or-none principle states that a muscle fibre contracts fully once a sufficient threshold is reached; below threshold it does not contract. More force is produced mainly by recruiting more motor units from small to large, not by making one unit contract more strongly.','全或无原则表示肌纤维达到足够阈值后会完全收缩，低于阈值则不收缩。力量增加主要来自从小到大的运动单位募集，而不是让一个单位收缩得更强。')],[nb('Type I fibres are slow, oxidative and fatigue-resistant; Type IIa are fast and use both aerobic and glycolytic metabolism; Type IIx are very fast, glycolytic and powerful but fatigue quickly.','I型纤维慢、有氧、耐疲劳；IIa型快速，结合有氧和糖酵解；IIx型极快、依赖糖酵解、力量强但很快疲劳。')],[nb('Motor unit','运动单位', 'One motor neuron and the muscle fibres it innervates.','一个运动神经元及其支配的肌纤维。'),nb('Hypertrophy','肌肥大', 'Increase in fibre cross-sectional area after training.','训练后肌纤维横截面积增加。'),nb('Atrophy','肌萎缩', 'Decrease in fibre cross-sectional area after detraining or inactivity.','停训或不活动后肌纤维横截面积减少。')],[],[nb('Sprinters rely more on fast powerful fibres, while distance runners rely more on fatigue-resistant fibres.','短跑者更多依赖快速高功率纤维，长跑者更多依赖耐疲劳纤维。')],[nb('Apply the size principle to a strength task.','把募集大小原则应用到力量任务。')],[nb('Compare Type I, IIa and IIx fibres.','比较I型、IIa型和IIx型肌纤维。')])
,ns('Contractions and muscle interaction',[nb('An isometric contraction produces force without joint movement. A concentric contraction shortens muscle against resistance. An eccentric contraction lengthens active muscle while controlling resistance. An isokinetic contraction occurs at constant speed through the range of motion.','等长收缩产生力量但关节不移动；同心收缩在克服阻力时肌肉缩短；离心收缩时主动肌肉在控制阻力中延长；等动收缩以恒定速度完成全范围运动。')],[nb('The agonist is the prime mover; the antagonist opposes it. Reciprocal inhibition helps the agonist act without simultaneous strong antagonist contraction.','主动肌是主要产生动作的肌肉，拮抗肌与其作用相反。交互抑制帮助主动肌动作而不让拮抗肌同时强烈收缩。')],[nb('Concentric','同心收缩', 'Active muscle shortens.','主动肌肉缩短。'),nb('Eccentric','离心收缩', 'Active muscle lengthens under load.','主动肌肉在负荷下延长。')],[],[nb('In a biceps curl, the biceps is the agonist and triceps the antagonist during flexion; lowering the weight is eccentric for the biceps.','弯举屈肘时，肱二头肌是主动肌，肱三头肌是拮抗肌；放下重量时肱二头肌进行离心收缩。')],[nb('Identify contraction type, motor-unit change and adaptation in a strength task.','在力量任务中识别收缩类型、运动单位变化和适应。')],[nb('Describe and give an example of each contraction type.','描述每种收缩类型并举例。')])
,ns('Recruitment, adaptations and sliding filament',[nb('Hypertrophy increases cross-sectional area and can increase force; atrophy reduces cross-sectional area and force. ATP is required for cross-bridge cycling and calcium reuptake during relaxation. In the sliding-filament model, calcium binds troponin and moves tropomyosin away from actin binding sites, myosin binds and pulls actin, ADP and phosphate are released, ATP detaches the bridge, and ATP hydrolysis re-cocks the head.','肌肥大增加横截面积并可增加力量；肌萎缩减少横截面积和力量。横桥循环和松弛时钙回收都需要ATP。滑动肌丝模型中，钙与肌钙蛋白结合，使原肌球蛋白移开肌动蛋白结合位点；肌球蛋白结合并拉动肌动蛋白，ADP和无机磷酸释放，ATP使横桥分离，ATP水解使肌球蛋白头部重新准备。')],[nb('A motor unit is recruited from small to large as force demand rises.','力量需求增加时，运动单位由小到大募集。')],[nb('All-or-none principle','全或无原则', 'A fibre contracts fully after threshold stimulation.','达到阈值刺激后肌纤维完全收缩。')],[],[nb('Strength training can increase force through recruitment and hypertrophy; slowing the lowering phase emphasises eccentric control.','力量训练可通过募集和肌肥大增加力量；放慢下降阶段可强调离心控制。')],[nb('Outline the sliding-filament theory.','概述滑动肌丝理论。')],[nb('Why is ATP needed for both contraction and relaxation?','为什么收缩和松弛都需要ATP？')])
],examFocus:[nb('Connect motor-unit recruitment, fibre type, contraction and adaptation to a sport task; do not overlearn molecular details.')],quickCheck:[nb('Define a motor unit and the all-or-none principle.','定义运动单位和全或无原则。')]},
{code:'B.1.4',page:13,theme:'B',title:nb('Levers in movement and sport','人体杠杆与运动'),guidingQuestion:nb('How do lever arrangements change force, speed and range of motion?','杠杆排列如何改变力量、速度和关节活动范围？'),intro:nb('Every lever contains an effort, a fulcrum and a load. Their positions determine the class and the trade-off between force, speed and range of motion. Equipment can act as an external lever to extend the body’s mechanical options.','每个杠杆都包含动力、支点和阻力。它们的位置决定杠杆类别，也决定力量、速度和活动范围之间的取舍。装备可作为外杠杆，扩展身体的力量学选择。'),sections:[
ns('Components and lever classes',[nb('Bones act as levers, joints as fulcrums, muscles as effort and body parts or objects as load. A first-class lever has the fulcrum between effort and load, a second-class lever has the load between fulcrum and effort, and a third-class lever has the effort between fulcrum and load.','骨作为杠杆，关节作为支点，肌肉提供动力，身体部位或物体作为阻力。一类杠杆的支点在动力和阻力之间；二类的阻力在支点和动力之间；三类的动力在支点和阻力之间。')],[nb('Second-class levers always have a force advantage. Third-class levers always have a speed and range-of-motion advantage. First-class levers can vary depending on arm lengths.','二类杠杆总是具有力量优势；三类杠杆总是具有速度和活动范围优势；一类的效果取决于两臂长度。')],[nb('Effort arm','动力臂', 'Distance from fulcrum to effort.','支点到动力作用点的距离。'),nb('Load arm','阻力臂', 'Distance from fulcrum to load.','支点到阻力作用点的距离。')],[],[nb('The triceps push-down and knee extension are second-class examples; the biceps curl is third-class; the atlanto-occipital joint is first-class.','肱三头肌下压和膝伸展是二类例子；肱二头肌弯举是三类；寰枕关节是一类。')],[nb('Classify the elbow and explain one equipment change to its lever system.','对肘关节分类，并解释一种器械调整。')],[nb('Label effort, fulcrum and load on a lever.','在杠杆上标出动力、支点和阻力。')])
,ns('Mechanical advantage and equipment',[nb('Mechanical advantage is effort arm divided by load arm. A value above 1 gives a force advantage, 1 is neutral, and below 1 gives a speed or range advantage. Increasing effort arm or decreasing load arm increases mechanical advantage; the reverse favours speed and range.','机械优势是动力臂除以阻力臂。大于1表示力量优势，等于1为中性，小于1表示速度或范围优势。增加动力臂或减小阻力臂会提高机械优势，反之则有利于速度和范围。')],[nb('Longer bats, rackets, paddles and poles can increase reach, power, swing speed, propulsion or energy return, depending on the task.','更长的球棒、球拍、球板和撑杆可按任务需要增加触及范围、功率、挥拍速度、推进力或能量回收。')],[nb('Mechanical advantage','机械优势', 'Ratio of effort arm to load arm.','动力臂与阻力臂的比值。')],[{en:'Mechanical advantage',zh:'机械优势',formula:'MA = effort arm / load arm',formulaZh:'机械优势 = 动力臂 ÷ 阻力臂'}],[],[nb('Moving the load farther from the fulcrum increases load arm and can reduce force advantage while increasing speed or range.','将阻力远离支点会增加阻力臂，可能降低力量优势并提高速度或范围。')],[nb('Change MA = EA / LA','改变MA = EA / LA')],[nb('Which lever class gives the greatest force advantage and which gives the greatest speed advantage?','哪类杠杆力量优势最大？哪类杠杆速度优势最大？')])
],examFocus:[nb('Identify lever classes from positions, use MA = effort arm / load arm, and justify an equipment change.')],quickCheck:[nb('How can changing EA or LA affect mechanical advantage?','动力臂或阻力臂变化如何影响机械优势？')]},
{code:'B.2.1',page:14,theme:'B',title:nb('Newton’s laws of motion','牛顿运动定律'),guidingQuestion:nb('How can forces explain linear and angular movement in sport?','力如何解释运动中的直线和角运动？'),intro:nb('Newton’s three laws link force to inertia, acceleration, action and reaction. Linear and angular variables, stability, impulse, momentum, collisions, friction, work and power connect those principles to sporting performance.','牛顿三定律将力与惯性、加速度、作用和反作用联系起来。直线和角运动变量、稳定性、冲量、动量、碰撞、摩擦、功和功率把这些原理与运动表现连接起来。'),sections:[
ns('Three laws and motion variables',[nb('The first law says an object remains at rest or in uniform straight-line motion unless a resultant force acts. The second law is F = ma: resultant force equals mass multiplied by acceleration. The third law says every action has an equal and opposite reaction.','第一定律指出除非有合外力作用，物体保持静止或匀速直线运动。第二定律为F = ma：合外力等于质量乘以加速度。第三定律指出每个作用力都有大小相等、方向相反的反作用力。')],[nb('Linear motion is described by speed, velocity, acceleration and momentum p = mv. Angular motion is described by angular velocity, angular acceleration, moment of inertia and torque.','直线运动用速度、速率、加速度和动量p = mv描述；角运动用角速度、角加速度、转动惯量和扭矩描述。')],[nb('Inertia','惯性', 'Resistance to a change in state of motion.','改变运动状态的抵抗。'),nb('Momentum','动量', 'Quantity of motion, p = mv.','运动量，p = mv。')],[{en:'Second law',zh:'第二定律',formula:'F = ma',formulaZh:'F = ma'}],[],[nb('A swimmer pushes backwards on the block, and the block pushes the swimmer forwards with an equal and opposite force.','游泳者向后推蹬板，蹬板以大小相等、方向相反的力推动游泳者向前。')],[nb('State Newton’s three laws with a sport example.','说出牛顿三定律并给出运动例子。')],[nb('Compare linear velocity and angular velocity.','比较直线速度和角速度。')])
,ns('Stability, impulse and collisions',[nb('Stability depends on the base of support, centre-of-mass height, line of gravity and mass. A low centre of mass and a line of gravity inside the base improve stability; more mass increases inertia. Impulse is force multiplied by time and changes momentum. In a collision, momentum is conserved and coefficient of restitution describes how much velocity is retained.','稳定性取决于支撑面、重心高度、重力线和质量。较低的重心以及位于支撑面内的重力线提高稳定性；更大质量增加惯性。冲量是力乘以时间，用于改变动量。碰撞中动量守恒，恢复系数描述速度保留程度。')],[nb('A penalty kick uses a force over a contact time to change ball momentum. A tennis forehand applies force away from the axis to create torque and spin.','罚球通过一段时间的力改变球的动量；网球正手在远离轴的位置施力，产生扭矩和旋转。')],[nb('Torque','扭矩', 'Turning effect of a force about an axis, T = r × F.','力绕轴产生的转动作用，T = r × F。')],[{en:'Impulse',zh:'冲量',formula:'J = FΔt = Δp',formulaZh:'J = FΔt = Δp'},{en:'Momentum',zh:'动量',formula:'p = mv',formulaZh:'p = mv'},{en:'Work',zh:'功',formula:'W = Fd cosθ',formulaZh:'W = Fd cosθ'},{en:'Power',zh:'功率',formula:'P = W/t',formulaZh:'P = W/t'}],[],[nb('Apply impulse to a longer or shorter contact: the same force for longer time changes momentum more, while power is work per unit time.','将冲量应用于更长或更短接触：相同力作用更久会改变更多动量，而功率是单位时间内做的功。')],[nb('Explain how impulse, work and power differ in a jump.','解释跳跃中冲量、功和功率的区别。')],[nb('What quantities are conserved in a collision?','碰撞中什么量守恒？')])
,ns('Friction, work and power',[nb('Friction opposes motion between surfaces and can be static, kinetic or rolling; air resistance is drag. Work is force multiplied by displacement in the direction of force, while power is the rate of doing work. Technique, equipment, contact time, grip and aerodynamic design can optimise useful work and reduce unwanted resistance.','摩擦阻碍表面间运动，可分为静摩擦、动摩擦和滚动摩擦；空气阻力是阻力。功是力沿位移方向的乘积，功率是做功速率。技术、装备、接触时间、抓握和空气动力学设计可优化有效做功并减少不必要阻力。')],[nb('A sprinter can use a smooth surface and footwear to reduce unwanted friction while applying force in the direction of travel.','短跑者可以使用平整地面和合适的鞋减少不必要摩擦，同时沿运动方向施力。')],[nb('Coefficient of restitution','恢复系数', 'Ratio of relative separation speed to relative approach speed after collision.','碰撞后分离相对速度与接近相对速度之比。')],[],[nb('A ball can travel farther with higher release speed or a larger weight-to-drag ratio; increasing contact time can change impulse and power.','球以更高出手速度或更大重量/阻力比可飞得更远；增加接触时间会改变冲量和功率。')],[nb('How can technique and equipment optimise power?','技术和装备如何优化功率？')],[nb('Compare friction, work and power in a sport.','在运动中比较摩擦、功和功率。')])
],examFocus:[nb('Use the data-booklet equations and explain variables; trigonometry is not required.')],quickCheck:[nb('How do forces produce a change in linear or angular motion?','力如何产生直线或角运动变化？')]},
{code:'B.2.2',page:15,theme:'B',title:nb('Fluid mechanics','流体力学'),guidingQuestion:nb('How do air and water forces alter projectile and body movement?','空气和水的力如何改变抛体与身体运动？'),intro:nb('Fluid mechanics examines how gravity, drag, lift, buoyancy and thrust act in air or water. Initial velocity, release angle and height, environmental density, equipment and technique all influence performance and fairness.','流体力学研究空气或水中重力、阻力、升力、浮力和推力的作用。初速度、出手角和高度、环境密度、装备与技术都影响表现和公平。'),sections:[
ns('Projectile motion and environmental forces',[nb('A projectile follows a curved path because gravity acts downwards and drag opposes motion. Initial velocity, release angle and release height influence distance and flight time. A higher weight-to-air-resistance ratio allows an object to maintain speed and travel farther.','抛体因重力向下和阻力反向作用而沿曲线飞行。初速度、出手角和出手高度影响距离与飞行时间。较高的重量/空气阻力比可保持速度并飞得更远。')],[nb('Temperature, humidity, air pressure, wind, water salinity and altitude change fluid density and therefore force. Headwinds increase drag; tailwinds reduce relative drag; salt water increases buoyancy; altitude reduces air density while also reducing oxygen availability.','温度、湿度、气压、风、水盐度和海拔改变流体密度及作用力。逆风增加阻力，顺风减小相对阻力，盐水增加浮力；海拔升高降低空气密度，同时也降低氧气可用性。')],[nb('Drag','阻力', 'Fluid resistance opposing relative motion. ' + '','阻碍相对运动的流体阻力。')],[],[],[nb('A javelin released high and fast can travel farther, but a tailwind and low drag also affect official distance.','标枪出手更高、更快可飞得更远，但顺风和低阻力也会影响正式距离。')],[nb('What determines the flight of a projectile?','什么决定抛体的飞行？')],[nb('Name three environmental factors that influence fluid forces.','说出三个影响流体作用力的环境因素。')])
,ns('Buoyancy, lift and drag',[nb('Buoyancy is the upward force from a fluid. Lift is a force that can redirect movement, such as hand-generated lift in swimming or aerodynamic lift around a ball. Drag is the opposing fluid force. Surface drag depends on skin friction, form drag on pressure and shape, and wave drag on waves in the medium.','浮力是流体向上的作用力；升力可改变运动方向，如游泳中由划手产生的升力或球周围的空气升力；阻力是相反的流体作用力。表面阻力与皮肤摩擦有关，形状阻力与压力和形状有关，波阻力来自介质中的波。')],[nb('Streamlined body position reduces form drag; a smooth stroke can reduce resistance and improve propulsion.','流线型身体位置可减少形状阻力；平滑划水可减少阻力并提高推进力。')],[nb('Buoyancy','浮力', 'Upward force from a fluid.','流体产生的向上作用力。'),nb('Lift','升力', 'Force that can redirect movement.','可改变运动方向的作用力。')],[],[nb('A swimmer lowers the head and presents a smoother body line; evaluate the likely effect on drag.','游泳者降低头部并使身体线条更流线；评价其对阻力的可能影响。')],[nb('Explain one technique that reduces drag and one ethical or regulatory issue.','解释一种减阻技术和一个伦理或规则问题。')],[nb('Define buoyancy, lift and drag with an example.','定义浮力、升力和阻力并举例。')])
,ns('Angle of attack, Magnus effect and fairness',[nb('Bernoulli’s principle links faster fluid flow with lower pressure. Angle of attack is the angle between an object and oncoming flow; too large an angle can produce a stall and increased drag. The Magnus effect is the pressure difference created by spin, producing a curved or lifted flight path.','伯努利原理把更快流体与较低压力联系起来。攻角是物体与来流之间的夹角；攻角过大会产生失速并增加阻力。马格努斯效应是旋转形成的压力差，可使飞行产生升力或弯曲。')],[nb('Equipment rules may limit technological advantage, and wind readings affect official records in athletics.','装备规则可能限制技术优势，风速读数会影响田径正式纪录。')],[nb('Angle of attack','攻角', 'Angle between an object and oncoming fluid flow.','物体与来流之间的夹角。'),nb('Magnus effect','马格努斯效应', 'Pressure difference caused by spin.','旋转造成的压力差。')],[],[nb('A spinning football can curve, but a high angle can also increase drag; equipment and environmental effects must be interpreted fairly.','旋转足球可以弯曲飞行，但过大攻角也会增加阻力；装备和环境影响应公平解读。')],[nb('How do angle of attack and spin influence lift?','攻角和旋转如何影响升力？')],[nb('Describe three types of drag and their implications.','描述三种阻力及其影响。')])
],examFocus:[nb('Relate forces to technique and equipment, and include ethical and regulatory implications; do not use advanced fluid equations.')],quickCheck:[nb('How can a projectile be optimised without treating all environmental effects as equal?','如何在考虑环境影响差异的情况下优化抛体？')]},
{code:'B.2.3',page:16,theme:'B',title:nb('Movement analysis and applications','动作分析与应用'),guidingQuestion:nb('How can breaking a movement into phases improve performance, safety and accessibility?','将运动分解为阶段如何提高表现、安全和无障碍参与？'),intro:nb('Phase analysis divides a discrete skill into preparatory, force-production, critical-instant and follow-through or recovery phases. Observation, video, technology and athlete feedback then form an evidence loop for diagnosis, intervention and refinement.','阶段分析将离散技能分为准备、发力、关键瞬间以及随动或恢复阶段。观察、视频、技术和运动员反馈形成证据循环，用于诊断、干预和完善。'),sections:[
ns('Phases and the diagnosis loop',[nb('In a tennis serve, preparation sets the stance and coordinates the body; force production generates speed; the critical instant is ball contact; follow-through directs force across the body and finishes balanced.','网球发球中，准备阶段建立站姿并协调身体；发力阶段产生速度；关键瞬间是击球；随动将力引导过身体并以平衡结束。')],[nb('Observe, analyse phases, diagnose causes, intervene and review. Small improvements in each phase can create a large overall change.','观察、分析阶段、诊断原因、干预并复查。每个阶段的小改进可能带来整体大变化。')],[nb('Critical instant','关键瞬间', 'The event that determines the skill outcome.','决定技能结果的关键事件。')],[],[nb('If contact is late, the intervention may be to change preparation or timing, then retest rather than adding an unrelated cue.','若击球偏晚，干预可以是改变准备或时机，然后重新测试，而不是添加无关提示。')],[nb('Explain how phase analysis improves performance and safety.','解释阶段分析如何提高表现和安全。')],[nb('Name the four phases of a discrete skill.','说出离散技能的四个阶段。')])
,ns('Evidence sources and compensation',[nb('Observation uses checklists and notational analysis to record what, when, how often and with what outcome. Video allows slow motion, frame-by-frame review, angles and comparison over time. Technology such as GPS, IMUs, force plates, timing gates and jump mats supplies speed, force, power, angle and time data. Athlete feedback adds RPE, comfort, confidence and goals.','观察使用检查表和记谱法记录发生了什么、何时发生、频率及结果。视频可慢放、逐帧、改变角度并比较不同时间。GPS、惯性测量器、测力台、计时门和跳跃垫可提供速度、力量、功率、角度和时间数据。运动员反馈补充RPE、舒适度、自信心和目标。')],[nb('Common compensation signs include asymmetry, reduced range, poor timing or sequencing, excessive joint load, pain and discomfort. Possible impacts include lower performance, higher energy cost and overuse injury.','常见代偿包括不对称、活动范围减少、时机或顺序差、关节负荷过大、疼痛和不适；可能影响表现、增加能量成本和过度使用损伤。')],[nb('Notational analysis','记谱分析', 'Systematic recording of observed movement features.','系统记录观察到的动作特征。')],[],[nb('Use athlete feedback with video rather than diagnosing pain or pathology from video alone.','将运动员反馈与视频结合，不应仅凭视频诊断疼痛或病理。')],[nb('List two evidence sources used in movement analysis.','列出动作分析中的两种证据来源。')],[nb('How does the diagnosis loop work?','诊断循环如何运作？')])
,ns('Rehabilitation and accessibility',[nb('Analysis supports restore, re-educate and return: restore mobility, strength and control; re-educate technique and movement patterns; then add gradual sport-specific load. Accessibility adaptations can change technique, equipment or task constraints: lighter rackets or larger handles, a lower net or softer ball, reduced distance, slower speed, clear cues and assistive devices.','动作分析支持恢复、再教育和回归：恢复活动度、力量和控制；重新教育技术和动作模式；再逐步加入专项负荷。无障碍调整可改变技术、装备或任务条件：更轻的球拍或更长的把手、更低的球网或更软的球、缩短距离、降低速度、清晰提示和辅助设备。')],[nb('Adapt the constraints to enable success, not the athlete to fit an unsuitable task.','调整限制条件以促进成功，而不是要求运动员适应不合适任务。')],[nb('Accessibility','无障碍参与', 'Removing barriers and adapting tasks or equipment so participation is possible.','去除障碍并调整任务或装备，使参与成为可能。')],[],[nb('A player with limited grip strength can use a larger or lighter racket, then progress the task gradually.','握力有限的球员可使用更大或更轻的球拍，再逐步增加任务难度。')],[nb('Give one technique, equipment and task adaptation.','各给出一个技术、装备和任务调整。')],[nb('How can analysis increase accessibility?','动作分析如何提高无障碍参与？')])
],examFocus:[nb('Use a phase, evidence source, change and retest; avoid exact joint angles, pathology or detailed kinetics.')],quickCheck:[nb('What is the complete analysis cycle?','完整的动作分析循环是什么？')]},
{code:'B.3.1',page:17,theme:'B',title:nb('Causes of injury','损伤原因'),guidingQuestion:nb('Why do internal and external factors make some athletes more susceptible to injury?','为什么内部和外部因素会使一些运动员更易受伤？'),intro:nb('Injury risk is the interaction of internal factors, external factors and exposure. A risk factor increases likelihood but does not guarantee injury. Acute trauma follows a sudden or excessive force, while cumulative trauma follows repeated force without adequate recovery.','损伤风险由内部因素、外部因素和暴露共同作用。风险因素增加可能性但不保证受伤。急性创伤由突然或过大的力导致，累积性损伤由反复受力且恢复不足导致。'),sections:[
ns('Internal and external risk factors',[nb('Internal factors include age and growth spurts, pregnancy-related hormonal and postural changes, congenital structural variation, joint laxity, poor posture and previous injury. External factors include sex-related differences, poor or absent protective equipment, environment, facility and surface conditions, travel, training load, technique and fatigue.','内部因素包括年龄和生长突增、孕期激素与姿势变化、先天结构差异、关节松弛、不良姿势和既往损伤。外部因素包括性别相关差异、防护装备缺失或不当、环境设施和场地、旅行、训练负荷、技术和疲劳。')],[nb('Previous injury can reduce strength, balance or proprioception and alter mechanics, increasing reinjury risk.','既往损伤可降低力量、平衡或本体感觉并改变动作，增加再伤风险。'),nb('A risk factor is a probability factor, not a diagnosis.','风险因素是概率因素，不是诊断。')],[nb('Exposure','暴露', 'The amount and type of activity or load experienced.','经历的活动或负荷的类型与数量。'),nb('Previous injury','既往损伤', 'An earlier injury that can affect current risk and function.','影响当前风险和功能的既往损伤。')],[],[nb('Manage controllable factors such as load, technique, recovery, equipment and surface; do not claim that every factor can be changed.','管理负荷、技术、恢复、装备和场地等可控因素；不要声称所有因素都能改变。')],[nb('Classify a scenario and identify controllable risk factors.','对情境分类并识别可控风险因素。')],[nb('Give two internal and two external risk factors.','给出两个内部和两个外部风险因素。')])
,ns('Acute and cumulative trauma',[nb('Acute mechanisms include collision, fall, twisting or pivoting, overstretching or being struck by an object. The force is sudden or excessive and injury may be immediate. Cumulative trauma follows repetitive loading, small tissue damage, inadequate recovery, poor technique or training errors over time.','急性机制包括碰撞、跌倒、扭转或变向、过度伸拉或被物体击中。力量突然或过大，损伤可能立即发生。累积性损伤由反复负荷、小量组织损伤、恢复不足、技术不佳或训练错误随时间累积造成。')],[nb('Overuse examples include shin splints, tendinopathy and stress fractures. Biomechanical maladaptation can produce persistent pain, reduced performance, increased risk and longer recovery.','过度使用损伤例子包括胫骨疼痛、肌腱病和应力性骨折。生物力学适应不良可造成持续疼痛、表现下降、风险增加和恢复延长。')],[nb('Acute trauma','急性创伤', 'Sudden injury from unexpected or excessive force.','由突然或过大力导致的损伤。'),nb('Cumulative trauma','累积性损伤', 'Gradual injury from repeated load and inadequate recovery.','由反复负荷和恢复不足造成的渐进损伤。')],[],[nb('Hamstring pain worsening over several weeks as mileage rises is cumulative, not necessarily a single acute tear.','随着里程增加，数周内逐渐加重的腘绳肌疼痛属于累积性问题，不一定是单次急性撕裂。')],[nb('Difference between acute and overuse injuries.','区分急性和过度使用性损伤。')],[nb('Why is poor technique an injury risk factor?','为什么技术不佳是损伤风险因素？')])
,ns('Tissues and concussion',[nb('Connective tissue injuries include sprains, strains, tendinopathy and cartilage damage. Muscle injuries include strains, tears and contusions. Bone injuries include fractures, stress fractures and bruising. Skin injuries include grazes, blisters, lacerations and burns. The brain can have a functional injury such as concussion without visible structural damage.','结缔组织损伤包括扭伤、拉伤、肌腱病和软骨损伤；肌肉损伤包括拉伤、撕裂和挫伤；骨损伤包括骨折、应力性骨折和骨挫伤；皮肤损伤包括擦伤、水疱、裂伤和烧伤。脑震荡是功能性损伤，可能没有可见结构损伤。')],[nb('Concussion symptoms may include headache, dizziness, confusion, nausea and sensitivity to light. It must be managed correctly.','脑震荡症状可能包括头痛、头晕、困惑、恶心和对光敏感，必须正确管理。')],[nb('Functional injury','功能性损伤', 'A change in function without visible structural damage, such as concussion.','没有可见结构损伤的功能改变，如脑震荡。')],[],[nb('Classify the tissue first, then connect the likely injury mechanism to the structure affected.','先判断组织，再把可能的损伤机制与受影响结构联系起来。')],[nb('How do tissue function and injury mechanism connect?','组织功能与损伤机制如何联系？')],[nb('Name one injury example for each of two tissues.','为两种组织各举一个损伤例子。')])
],examFocus:[nb('Use risk, exposure and mechanism; do not overlearn pathology, drugs, surgery or detailed brain anatomy.')],quickCheck:[nb('Why is a previous injury a risk factor?','为什么既往损伤是风险因素？')]},
{code:'B.3.2',page:18,theme:'B',title:nb('Interventions related to injury','损伤干预'),guidingQuestion:nb('How can injury risk be reduced and recovery managed safely?','如何降低损伤风险并安全管理恢复？'),intro:nb('Interventions should reduce abnormal force, improve force absorption, use correctly fitted protective equipment, prepare the body and use correct technique. Healing, rehabilitation and return to activity progress gradually, while concussion return is staged and symptom-led.','干预应减少异常力、改善冲击力吸收、使用正确贴合的防护装备、做好身体准备并使用正确技术。愈合、康复和重返活动逐步进行，脑震荡回归则按阶段和症状管理。'),sections:[
ns('Prevention and protection',[nb('To reduce abnormal force, use appropriate training load, adequate rest, safe surfaces, strong and flexible muscles, neuromuscular control, good technique and shock-absorbing equipment. Developmentally appropriate rules and progressive skill learning also reduce exposure to unnecessary risk.','减少异常力需要合适训练负荷、充分休息、安全场地、强韧灵活肌肉、神经肌肉控制、正确技术和缓冲装备。符合发展阶段的规则和渐进技能学习也能减少不必要的风险暴露。')],[nb('Protective equipment must be sport- and position-specific, correctly sized, comfortable, secure, compliant and reassessed as the athlete grows or changes role.','防护装备应符合项目和位置、尺寸正确、舒适、牢固、符合标准，并随着运动员生长或角色变化重新评估。')],[nb('Prehabilitation','预康复', 'Preparing vulnerable or weak areas before injury or high demand.','在受伤或高负荷前准备薄弱或易受伤区域。'),nb('Force absorption','冲击力吸收', 'The ability to spread or reduce an external load.','分散或降低外部负荷的能力。')],[],[nb('A basketball player uses strength and landing technique to reduce ACL and ankle risk; a runner increases weekly distance gradually and varies surfaces.','篮球运动员用力量和落地技术降低膝前交叉韧带和踝部风险；跑者逐步增加周里程并变换地面。')],[nb('How can prehabilitation, warm-up and technique reduce risk?','预康复、热身和技术如何降低风险？')],[nb('What should be checked when selecting protective equipment?','选择防护装备时应检查什么？')])
,ns('PRICE, healing and rehabilitation',[nb('PRICE means protection, rest, ice, compression and elevation during the first 48–72 hours. NSAIDs may be used short term to manage pain and inflammation but do not speed tissue healing and require appropriate safeguards. Tissue healing progresses from inflammation to repair and remodelling.','PRICE包括保护、休息、冰敷、加压和抬高，用于最初48–72小时。短期使用非甾体抗炎药可管理疼痛和炎症，但不会加快组织愈合，并需适当注意安全。组织愈合从炎症进入修复和重塑。')],[nb('Rehabilitation progresses from restoring movement to restoring power and sport-specific performance. Heat, ice, ultrasound and electrical stimulation may assist pain or recovery but are not substitutes for progressive loading.','康复从恢复活动度逐步发展到恢复力量和专项表现。热疗、冰疗、超声和电刺激可帮助疼痛或恢复，但不能替代渐进负荷。')],[nb('Protection','保护', 'Prevent further injury while symptoms settle.','在症状稳定时防止进一步损伤。'),nb('Remodelling','重塑', 'The later stage in which tissue is reorganised and adapted.','组织重新组织并适应的后期阶段。')],[],[nb('A clinician may use surgery for severe tears or fractures, but the course is individualised and followed by post-operative protocol.','严重撕裂或骨折可能需要手术，但过程应个体化并遵循术后方案。')],[nb('Place a treatment in prevention, acute management, rehabilitation or return to sport.','将处理归入预防、急性管理、康复或重返运动。')],[nb('What is the sequence from healing to return to performance?','从愈合到重返表现的顺序是什么？')])
,ns('Staged concussion return',[nb('Concussion progression is symptom-free at each stage. The sequence is relative rest, light cognitive activity and daily living, school or work reintroduction with light aerobic activity, sport-specific running drills without head impact, non-contact training, full-contact practice and return to normal sport. Red flags require stopping and medical review.','脑震荡每次进阶前都应无症状。顺序是相对休息、轻度认知活动和日常生活、学校或工作恢复配合轻度有氧、无头撞击的专项跑动、无接触训练、全接触练习，最后恢复正常运动。出现红旗症状应停止并接受医疗评估。')],[nb('A symptom return means step back to the previous tolerated stage rather than pushing through.','症状复发意味着退回上一个可耐受阶段，而不是硬撑。')],[nb('Return to sport','重返运动', 'The final stage after symptom-free progression through daily, cognitive and sport demands.','经过日常、认知和运动需求且无症状后的最后阶段。')],[],[nb('Drowsiness, repeated vomiting, worsening headache, confusion, seizure, neck pain, weakness, tingling or slurred speech are red flags.','嗜睡、反复呕吐、头痛加重、困惑、癫痫、颈痛、无力、刺痛或言语含糊是红旗症状。')],[nb('Sequence a safe return from concussion.','排列脑震荡后的安全回归顺序。')],[nb('What should happen if symptoms return?','症状复发时应怎么办？')])
],examFocus:[nb('Organise interventions by purpose and sequence; do not memorise drug doses, surgery or exact rehabilitation exercises.')],quickCheck:[nb('How can abnormal force be reduced and force absorption improved?','如何减少异常力并改善冲击力吸收？')]},
{code:'C.1.1',page:19,theme:'C',title:nb('Personality','人格'),guidingQuestion:nb('How do stable traits and social experiences shape sporting behaviour?','稳定特质和社会经验如何塑造运动行为？'),intro:nb('Personality consists of relatively stable patterns of thought, feeling and behaviour. It emerges through interaction between traits and environment, influences tendencies rather than guarantees outcomes, and can change across the lifespan.','人格是相对稳定的思维、情感和行为模式。它通过特质与环境的互动形成，只影响行为倾向而不保证结果，并且可以随人生阶段变化。'),sections:[
ns('Trait-environment interaction',[nb('Traits are relatively stable and biologically influenced, while social, physical and situational environments provide coaches, peers, facilities, pressure and competition level. The same trait can produce different behaviour in different contexts.','特质相对稳定并受生物影响，社会、物理和情境环境则提供教练、同伴、设施、压力和竞争水平。相同特质在不同情境中可能产生不同行为。')],[nb('Personality can influence perception and appraisal, goals, motivation, coping, emotion regulation, decision making, risk taking and interpersonal behaviour.','人格可影响知觉和评价、目标、动机、应对、情绪调节、决策、风险选择和人际行为。')],[nb('Trait','特质', 'A relatively stable tendency within the person.','个人内部相对稳定的倾向。'),nb('Context','情境', 'The social and physical situation in which behaviour occurs.','行为发生的社会和物理情境。')],[],[nb('Two athletes with similar trait scores can behave differently because the task, pressure, environment and development differ.','两名运动员特质得分相近，却可能因任务、压力、环境和发展阶段不同而表现不同。')],[nb('Explain trait-environment interaction.','解释特质与环境的互动。')],[nb('Why can personality not simply predict performance?','为什么人格不能简单预测表现？')])
,ns('Big Five and measurement',[nb('The Big Five describes openness, conscientiousness, extraversion, agreeableness and emotional stability as broad dimensions with high and low ends. Traits are continua, not fixed categories. Validated self-report questionnaires use standardised items, scoring, reliability, validity and appropriate norms.','大五人格包括开放性、尽责性、外向性、宜人性和情绪稳定性，各维度有高低两端，特质是连续体而非固定类别。有效自评问卷使用标准化条目、评分、信度、效度和适当常模。')],[nb('Examples of use include Big Five Inventory, NEO PI-R, Sport Personality Scale and Competitive State Anxiety Inventory-2. Ethical use includes informed consent, confidentiality, appropriate interpretation and feedback for development.','应用例子包括大五人格问卷、NEO PI-R、运动人格量表和竞技状态焦虑量表-2。伦理使用包括知情同意、保密、适当解释和支持发展的反馈。')],[nb('Reliability','信度', 'Consistency of results.','结果的一致性。'),nb('Validity','效度', 'Evidence that a measure assesses what it intends to assess.','测量工具确实评估目标概念。')],[],[nb('Use the measure to identify a development opportunity, not to label or rank an athlete.','使用测量识别发展机会，而不是给运动员贴标签或排名。')],[nb('What qualities should a personality measure have?','人格测量应具备哪些质量？')],[nb('Name the five Big Five traits.','说出大五人格的五个特质。')])
,ns('Social learning and development',[nb('Social learning theory proposes observation, retention, reproduction and consequences. Athletes attend to role models, remember and reproduce behaviour, and are influenced by observed rewards or punishments. Higher-status or similar successful models can have greater influence.','社会学习理论包括观察、保持、再现和后果。运动员关注榜样，记忆并再现行为，同时受到观察到的奖励或惩罚影响。地位较高或相似且成功的榜样影响更大。')],[nb('Personality can change through maturation, experiences, success, failure, feedback, intentional practice, self-reflection, life events and supportive social environments.','人格可通过成熟、成功失败经验、反馈、有意练习、自我反思、生活事件和支持性社会环境改变。')],[nb('Self-fulfilling development','自我实现式发展', 'A supported tendency becomes stronger through practice and experience.','通过练习和经验，支持的倾向变得更稳定。')],[],[nb('A coach who models respectful effort and gives constructive feedback can support positive habits and persistence.','教练示范尊重努力并提供建设性反馈，可以支持积极习惯和坚持。')],[nb('How can personality develop over time?','人格如何随时间发展？')],[nb('Why is social learning relevant to sport?','为什么社会学习与运动相关？')])
],examFocus:[nb('Avoid deterministic labels; link traits to context, measurement quality and social learning.')],quickCheck:[nb('How do the same traits lead to different behaviour in two contexts?','相同特质如何在两种情境中产生不同行为？')]},
{code:'C.1.2',page:20,theme:'C',title:nb('Mental toughness','心理韧性'),guidingQuestion:nb('How do individuals respond differently to pressure and challenge?','个体如何以不同方式回应压力和挑战？'),intro:nb('Mental toughness supports consistent performance under pressure, adversity and challenge. The workbook’s five core attributes are challenge appraisal, commitment, confidence, perceived control and resilience. It is developable and interacts with health, sleep and attribution.','心理韧性支持压力、逆境和挑战下的稳定表现。工作册的五个核心属性是挑战评估、投入、自信、知觉控制和恢复力。它可以发展，并与健康、睡眠和归因相互作用。'),sections:[
ns('The five core attributes',[nb('Challenge appraisal treats pressure as an opportunity, commitment means staying with meaningful goals, confidence is trust in preparation, perceived control focuses on controllables, and resilience is recovery after setbacks.','挑战评估把压力视为机会，投入是坚持有意义的目标，自信是对准备的信任，知觉控制关注可控因素，恢复力是受挫后重新调整。')],[nb('A pressure moment may require all five attributes, but the relevant emphasis depends on the task and person.','压力情境可能需要全部五个属性，但重点取决于任务和个人。')],[nb('Challenge appraisal','挑战评估', 'Seeing pressure as growth rather than threat.','把压力看作成长而不是威胁。'),nb('Resilience','恢复力', 'Bouncing back and learning from adversity.','从逆境中恢复并学习。')],[],[nb('A basketball player views a close final quarter as a chance to prove themselves, focuses on controllables and resets after an error.','篮球运动员把关键的最后一节看作证明自己的机会，关注可控因素，并在失误后重新调整。')],[nb('Name and apply the five core attributes.','说出并应用五个核心属性。')],[nb('How do the five Cs support pressure performance?','五个C如何支持压力下表现？')])
,ns('Malleability and self-fulfilling belief',[nb('Mental toughness is malleable through goals, deliberate practice, reflection, challenge, stress management and feedback. A self-fulfilling prophecy can occur when confidence increases effort, persistence and effective strategies, improving performance and reinforcing confidence.','心理韧性可通过目标、有意练习、反思、挑战、压力管理和反馈发展。自信提高努力、坚持和有效策略，从而改善表现并进一步强化自信，形成自我实现预言。')],[nb('The MTQ48 is presented as a 48-item self-report tool measuring the five attributes. A score identifies strengths and areas for development rather than proving a guaranteed outcome.','MTQ48是测量五个属性的48项自评工具。得分可识别优势和发展领域，而不是证明必然结果。')],[nb('Malleable','可塑的', 'Capable of developing through experience and practice.','可通过经验和练习发展。')],[],[nb('An athlete who believes a difficult routine is learnable may practise more carefully, succeed and become more confident.','运动员相信困难动作可以学会时，可能更认真练习、成功并增强自信。')],[nb('Explain a self-fulfilling prophecy in sport.','解释运动中的自我实现预言。')],[nb('What is the MTQ48 used for?','MTQ48用于什么？')])
,ns('Learned helplessness, attribution and health',[nb('Learned helplessness develops when an athlete perceives no control, reduces effort and avoids challenge, which produces poorer performance and confirms the belief. Internal, unstable attributions such as “I can adjust my preparation next time” are generally more adaptive than stable, external explanations.','当运动员感知没有控制时，会减少努力、回避挑战，表现变差又强化该信念，形成习得性无助。内因、不稳定归因，例如“下次可以调整准备”，通常比稳定、外因解释更有适应性。')],[nb('Higher mental toughness is linked in the workbook with better stress management, fewer depressive or burnout symptoms, better sleep, positive mood and recovery.','工作册将较高心理韧性与更好的压力管理、更少的抑郁或倦怠症状、改善睡眠、积极情绪和恢复联系起来。')],[nb('Locus of control','控制点', 'Whether an explanation focuses on internal or external causes.','解释聚焦内部原因还是外部原因。'),nb('Stability','稳定性', 'Whether a cause is seen as changeable over time.','原因是否被认为会随时间改变。')],[],[nb('A player who misses a penalty may think “my routine needs adjusting” and practise, rather than “bad luck means I cannot change anything.”','罚球未进的球员可以想“我的流程需要调整”并训练，而不是认为“坏运气意味着无法改变”。')],[nb('How do internal, unstable attributions support motivation?','内因、不稳定归因如何支持动机？')],[nb('Name two health or wellbeing associations of mental toughness.','说出心理韧性的两项健康或福祉联系。')])
],examFocus:[nb('Use the five Cs, attribution and controllability; do not treat mental toughness as a guaranteed predictor.')],quickCheck:[nb('Use an internal, unstable attribution after failure to support persistence.','失败后采用内因、不稳定归因以支持坚持。')]},
{code:'C.2.1',page:21,theme:'C',title:nb('Motor learning processes','运动学习过程'),guidingQuestion:nb('How are skills acquired, practised and perfected?','技能如何获得、练习和完善？'),intro:nb('Motor learning is a relatively permanent change in capability; performance is what can be produced now and can fluctuate. Practice, feedback, schemas, stages, constraints, transfer and the environment shape learning.','运动学习是能力的相对永久变化；表现是当下能完成的内容，会波动。练习、反馈、图式、阶段、限制条件、迁移和环境共同塑造学习。'),sections:[
ns('Learning, performance and schemas',[nb('Learning occurs through practice, feedback and experience in the brain and nervous system. Performance is affected by fatigue, motivation, stress and environment. Information-processing theory links sensory input, decision making, response programming, output and feedback. A schema is a generalised memory of a skill that guides recognition and responses.','学习通过练习、反馈和经验发生在脑与神经系统；表现受疲劳、动机、压力和环境影响。信息加工理论把感觉输入、决策、反应编程、输出和反馈联系起来。图式是指导技能识别和反应的概括性记忆。')],[nb('Schema features include generality, flexibility, efficiency and updating with experience.','图式具有概括性、灵活性、效率，并随经验更新。')],[nb('Motor learning','运动学习', 'Relatively permanent change in capability.','能力的相对永久变化。'),nb('Performance','表现', 'What can be produced at a particular moment.','某一时刻能够完成的内容。')],[],[nb('A volleyball player uses a schema to choose a pass based on the position of the set and the conditions.','排球运动员利用图式，根据来球位置和情境选择传球。')],[nb('Differentiate motor learning and performance.','区分运动学习和表现。')],[nb('Outline the information-processing model.','概述信息加工模型。')])
,ns('Linear and non-linear pedagogy',[nb('Linear pedagogy uses progressive, step-by-step instruction. Open-loop theory plans before action and suits predictable self-paced skills; closed-loop theory uses feedback during and after movement and suits changing environments. Non-linear pedagogy uses performer, task and environmental constraints to encourage exploration and adaptability.','线性教学采用逐步教学。开放环理论在动作前制定计划，适合可预测的自定节奏技能；闭环理论在动作中或动作后使用反馈，适合变化环境。非线性教学利用表演者、任务和环境限制促进探索与适应。')],[nb('Ecological dynamics sees perception and action as coupled and movement as emerging from the performer, task and environment.','生态动力学把知觉和动作视为耦联，运动从表演者、任务和环境的互动中产生。')],[nb('Schema teaching','图式教学', 'Structured practice that develops and refines generalised movement memories.','发展并完善概括性动作记忆的结构化练习。'),nb('Constraints-led approach','限制引导法', 'Practice that manipulates constraints to guide exploration.','通过调整限制条件引导探索的练习。')],[],[nb('A coach can combine a clear technical model with a task that changes ball size, space or time so the learner explores adaptations.','教练可以把清晰技术模型与改变球大小、空间或时间的任务结合，让学习者探索调整。')],[nb('Compare schema teaching and a constraints-led session.','比较图式教学和限制引导课程。')],[nb('When should practice move from a simple movement to tactics or strategy?','练习何时应从基本动作转向战术或策略？')])
,ns('Stages, PRP and transfer',[nb('The cognitive stage has many errors, slow performance and high guidance needs. The associative stage refines the skill, reduces errors and improves consistency. The autonomous stage becomes more automatic, consistent under pressure and less dependent on feedback. The psychological refractory period means two tasks close together can delay the second response.','认知阶段错误多、表现慢、需要大量指导；联结阶段完善动作、减少错误、提高一致性；自主阶段更自动化、压力下更稳定、较少依赖反馈。心理不应期表示两个任务靠得很近时，第二个反应可能延迟。')],[nb('Six transfer types are skill-to-skill, practice-to-performance, bilateral, stage-to-stage, abilities-to-skills and principles-to-skills. Positive transfer helps; negative transfer can hinder.','六种迁移是技能到技能、练习到表现、双侧、阶段到阶段、能力到技能和原则到技能。正迁移促进学习，负迁移会阻碍。')],[nb('Overlearning can create stiffness and reduce adaptability, so practice should stop when the skill is consistent, effective and transferable.','过度练习会造成僵硬并降低适应性，因此技能一致、有效且可迁移时应停止。')],[nb('Psychological refractory period','心理不应期', 'A processing bottleneck that delays a second closely timed response.','使第二个紧邻任务反应延迟的信息加工瓶颈。')],[],[nb('Practising a chest pass can help a bounce pass; balance learned earlier can help advanced gymnastics.','练习胸前传球可帮助反弹传球；早期学习的平衡能力可帮助高级体操。')],[nb('Why should learners avoid overlearning?','为什么学习者应避免过度学习？')],[nb('Name the three stages of learning.','说出学习的三个阶段。')])
],examFocus:[nb('Know what each model explains and how it changes practice; do not memorise every researcher or phase detail.')],quickCheck:[nb('What is the difference between motor learning and performance?','运动学习和表现有什么区别？')]},
{code:'C.2.2',page:22,theme:'C',title:nb('Attentional control','注意控制'),guidingQuestion:nb('How does attentional focus influence skilled performance?','注意焦点如何影响熟练表现？'),intro:nb('Attention can be internal or external and broad or narrow. The focus should match the task: external focus often supports automatic, fluid performance, while internal focus is useful for early learning and technique correction.','注意可分为内部或外部、广义或狭窄。焦点应与任务匹配：外部焦点通常支持自动、流畅表现，内部焦点适合早期学习和技术纠正。'),sections:[
ns('Internal, external, broad and narrow',[nb('Internal attention focuses on the athlete’s body and technique, such as keeping the elbow aligned. External attention focuses on the effect or target, such as hitting the bottom-left corner of a goal. Broad attention processes more surroundings and suits open, dynamic skills; narrow attention processes little information and suits closed, self-paced tasks.','内部注意关注身体和技术，如保持肘部排列；外部注意关注效果或目标，如踢进球门左下角。广义注意处理更多环境信息，适合开放动态技能；狭窄注意处理信息较少，适合封闭、自定节奏任务。')],[nb('External focus is generally more effective for skilled performance, but internal focus can help initial learning.','外部焦点通常更有利于熟练表现，但内部焦点有助于初期学习。')],[nb('External focus','外部注意', 'Attention on the movement effect or environmental target.','关注动作效果或环境目标。'),nb('Attentional narrowing','注意狭窄', 'Reduced processing of peripheral information under high arousal.','高唤醒时减少外围信息加工。')],[],[nb('For a penalty, “see the target and trust the technique” uses an external focus; a long list of body instructions can overload attention.','罚球时“看到目标并相信技术”是外部焦点；过多身体指令会增加注意负荷。')],[nb('Define internal and external attention.','定义内部和外部注意。')],[nb('Give a penalty example of internal and external focus.','分别给出罚球中的内部和外部注意例子。')])
,ns('Distractors and control strategies',[nb('External distractors include crowd noise, movement, opponents, flash photography, flags, scoreboards and referee decisions. Internal distractors include worry, fear of failure, self-doubt, past errors, goal-irrelevant thoughts and excessive attention to fatigue or discomfort.','外部干扰包括人群噪声和运动、对手、闪光摄影、旗帜、记分牌和裁判判罚。内部干扰包括担忧、失败恐惧、自我怀疑、过去错误、与目标无关的想法和对疲劳或不适的过度关注。')],[nb('Pre-performance routines, breathing, focus cues, self-talk and process goals can clear irrelevant information and refocus. High arousal can create tunnel vision, fewer cues and poorer decisions.','赛前流程、呼吸、焦点提示、自我对话和过程目标可以清除无关信息并重新集中。高唤醒会造成隧道视野、线索减少和决策变差。')],[nb('Controlled distraction','受控分散', 'A deliberate cue or routine that redirects attention.','有意的提示或流程，用于重新引导注意。'),nb('Self-talk','自我对话', 'Internal statements used to guide attention and behaviour.','用于引导注意和行为的内部语言。')],[],[nb('A player bounces the ball twice, breathes and looks at the target before the attempt.','球员在罚球前运球两次、呼吸并看向目标。')],[nb('Classify a distraction and select one attentional-control strategy.','判断干扰类别并选择一种注意控制策略。')],[nb('How does high arousal affect attention?','高唤醒如何影响注意？')])
,ns('Task matching and self-talk',[nb('Use a broad external focus in invasion games and team sports to read teammates and opponents. Use a narrow external focus for a penalty, free throw or set play. Review and refocus before each attempt.','入侵游戏和团队运动使用广义外部注意以读取队友和对手；罚球、罚球或固定套路使用狭窄外部注意。每次尝试前复查并重新集中。')],[nb('“Don’t miss” can increase anxiety; “calm and focused” or “see the target” is more controllable and task-relevant.','“不要失误”可能增加焦虑；“保持冷静专注”或“看到目标”更可控、更贴近任务。')],[nb('Goal setting','目标设定', 'Setting process or performance goals to focus controllable actions.','设定过程或表现目标以关注可控行动。')],[],[nb('Practice with crowd noise or pressure cues so attentional control is trained, not assumed.','在人群噪声或压力提示下练习，使注意控制得到训练而不是靠假设。')],[nb('Choose the attentional width that fits a task.','为任务选择合适的注意广度。')],[nb('Give two external and two internal distractors.','给出两个外部和两个内部干扰。')])
],examFocus:[nb('Classify focus and distraction, then choose a context-appropriate intervention; no need for detailed attention-capacity models.')],quickCheck:[nb('How can an athlete control attention under pressure?','运动员如何在压力下控制注意？')]},
{code:'C.3.1',page:23,theme:'C',title:nb('Achievement motivation','成就动机'),guidingQuestion:nb('Why do some athletes approach achievement challenges while others avoid them?','为什么一些运动员主动迎接成就挑战，而另一些回避？'),intro:nb('Achievement motivation results from personality, situational factors, emotional factors and behaviour. Task orientation is self-referenced and values effort, learning and persistence; ego orientation is other-referenced and values winning and ability demonstration.','成就动机由人格、情境、情绪和行为共同影响。任务定向以自我为参照，重视努力、学习和坚持；自我定向以他人为参照，重视获胜和能力展示。'),sections:[
ns('Need achievement and orientations',[nb('Need achievement theory links personality factors such as need for achievement and learned experiences with situational factors such as task difficulty, goals, feedback, social climate, rewards and norms. The outcome is a tendency to approach or avoid achievement situations, effort, persistence and responses to success or failure.','成就需要理论把需要成就等人格因素与任务难度、目标、反馈、社会氛围、奖励和规范等情境因素联系起来。结果是接近或回避成就情境的趋势、努力、坚持以及对成败的反应。')],[nb('Task orientation focuses on self-referenced improvement, effort, learning, responsibility and enjoyment. Ego orientation focuses on outperforming others, winning, avoiding failure and protecting self-worth through outcomes.','任务定向关注自我参照的进步、努力、学习、责任和享受；自我定向关注胜过他人、获胜、避免失败以及通过结果保护自尊。')],[nb('Task orientation','任务定向', 'Self-referenced focus on learning, effort and improvement.','以自我为参照，关注学习、努力和进步。'),nb('Ego orientation','自我定向', 'Other-referenced focus on superiority and winning.','以他人为参照，关注优越和获胜。')],[],[nb('A task-oriented athlete asks for feedback, reflects and stays committed after a difficult session.','任务定向运动员寻求反馈、反思，并在困难训练后保持投入。')],[nb('Compare task and ego orientation.','比较任务定向和自我定向。')],[nb('List three features of each orientation.','分别列出两种定向的三个特征。')])
,ns('High ego with low ability and coach influence',[nb('High ego orientation with low perceived ability can increase anxiety, reduce effort, encourage excuses and blame, lead to withdrawal and limit potential. Coaches can reduce this by setting personal and process goals, matching task difficulty, giving specific constructive feedback, rewarding effort and improvement, and creating support and teamwork.','高自我定向配低知觉能力可能增加焦虑、减少努力、助长借口和责怪、导致退出并限制潜能。教练可通过个人和过程目标、匹配任务难度、具体建设性反馈、奖励努力和进步、营造支持与合作来减少这种风险。')],[nb('Reward structure, norms, social climate and task design send messages about what is valued.','奖励结构、规范、社会氛围和任务设计会传递“什么被重视”的信息。')],[nb('Perceived ability','知觉能力', 'The athlete’s belief about their capability.','运动员对自身能力的信念。'),nb('Approach behaviour','趋近行为', 'Taking on challenge and practising effort.','接受挑战并投入努力。')],[],[nb('Change “You are the best” to “Your preparation and decision improved this set.”','把“你是最棒的”改为“你的准备和决策让这一局有所改善”。')],[nb('How can coaches encourage approach behaviour?','教练如何鼓励趋近行为？')],[nb('What outcomes may occur with high ego orientation and low perceived ability?','高自我定向和低知觉能力可能导致哪些结果？')])
,ns('Coaching the environment',[nb('A coach can vary difficulty, set personal and process goals, provide feedback on improvement, encourage support and respect, reward effort and sportsmanship, and value learning and progress. These choices encourage challenge, effort, persistence and positive emotion.','教练可以调整难度，设定个人和过程目标，提供关于进步的反馈，鼓励支持与尊重，奖励努力和体育精神，并重视学习与进步。这些选择促进挑战、努力、坚持和积极情绪。')],[nb('Motivation is malleable because it changes with experience, feedback, goals and social climate.','动机具有可塑性，会随经验、反馈、目标和社交氛围改变。')],[nb('Social climate','社会氛围', 'The interpersonal and normative environment of the group.','团体的互动和规范环境。')],[],[nb('A team that rewards learning and effort is more likely to retain athletes and develop potential than a group focused only on winning.','奖励学习和努力的团队比只关注获胜的团队更可能保留运动员并发展潜能。')],[nb('Give two ways coaches can manipulate situational factors.','给出教练调节情境因素的两个方法。')],[nb('What is the difference between task and ego orientation?','任务定向和自我定向有什么区别？')])
],examFocus:[nb('Link personality and situation to emotional and behavioural outcomes; avoid mathematical equations and exact study statistics.')],quickCheck:[nb('Change a coach scenario from ego-supportive to task-supportive.','将教练情境从自我导向改为任务导向。')]},
{code:'C.3.2',page:24,theme:'C',title:nb('Self-determination','自我决定'),guidingQuestion:nb('How does satisfaction of psychological needs influence the quality of motivation?','心理需要的满足如何影响动机质量？'),intro:nb('Self-determination theory focuses on the quality of motivation. Autonomy, competence and relatedness support autonomous motivation, wellbeing and performance; need frustration is associated with controlled motivation or amotivation and poorer outcomes.','自我决定理论关注动机质量。自主、胜任和联结支持自主动机、福祉和表现；需要受挫与受控动机或无动机及较差结果相关。'),sections:[
ns('Three basic needs and continuum',[nb('Autonomy is feeling in control and having choice or volition. Competence is feeling effective and able to master challenges. Relatedness is feeling connected, valued and belonging. Need satisfaction supports autonomous motivation, persistence, enjoyment and mental health.','自主是感到有控制、有选择和意愿；胜任是感到有效并能掌握挑战；联结是感到连接、被重视和归属。需要满足支持自主动机、坚持、享受和心理健康。')],[nb('The continuum moves from amotivation through controlled and external/introjected regulation to identified, integrated and intrinsic motivation.','连续体从无动机，经过受控、外部和内摄调节，走向认同、综合和内在动机。')],[nb('Autonomy','自主', 'Experiencing choice and volition.','体验选择和意愿。'),nb('Competence','胜任', 'Feeling effective and able to improve.','感到有效并能改进。'),nb('Relatedness','联结', 'Feeling connected, valued and supported.','感到连接、被重视和支持。')],[],[nb('A coach offers choice, explains the reason for a task, gives optimal challenge, and builds inclusive team support.','教练提供选择，解释任务原因，给予适当挑战，并建立包容的团队支持。')],[nb('How do need satisfaction and need frustration affect motivation quality?','需要满足和受挫如何影响动机质量？')],[nb('Name the three basic psychological needs.','说出三种基本心理需要。')])
,ns('Controlled, autonomous and four extrinsic regulations',[nb('Controlled motivation is driven by reward, punishment, guilt, ego or shame and can have lower persistence, anxiety and wellbeing. Autonomous motivation is self-endorsed and linked to values or inherent enjoyment, with greater persistence, enjoyment and wellbeing. Extrinsic regulation can be external, introjected, identified or integrated, moving from “I must” to “I should” to “I want” because it matters to “I value” it.','受控动机由奖励、惩罚、内疚、自尊或羞耻驱动，可能带来较低坚持、较高焦虑和较低福祉。自主动机是自我认可，联系价值或内在享受，具有更高坚持、享受和福祉。外在调节可分外部、内摄、认同和综合，从“我必须”“我应该”到“我想要”再到“我重视”。')],[nb('A controlling reward can reduce intrinsic motivation through the overjustification effect; informational feedback and choice can support it.','控制性奖励可能通过过度理由效应降低内在动机；信息性反馈和选择可以支持内在动机。')],[nb('Overjustification effect','过度理由效应', 'A reduction in intrinsic motivation after controlling rewards are introduced.','引入控制性奖励后内在动机下降。')],[],[nb('“Train because I must avoid being dropped” differs from “train because it reflects who I am and what I value.”','“训练是因为我必须避免被淘汰”不同于“训练因为它反映了我是谁和我重视什么”。')],[nb('Explain how a controlling reward can reduce intrinsic motivation.','解释控制性奖励如何降低内在动机。')],[nb('Order the four extrinsic regulations by self-determination.','按自我确定程度排列四种外在调节。')])
,ns('Six mini-theories',[nb('The six mini-theories address context and intrinsic motivation, internalisation, causal orientations, basic needs, goal content and relationships. CET examines how autonomy support, informational feedback and optimal challenge affect intrinsic motivation. OIT explains internalisation over time. COT focuses on internal, stable and controllable causal attributions. BPNT connects autonomy, competence and relatedness. Goal contents theory distinguishes learning and ego goals. Relationship motivation theory focuses on caring coach-athlete and teammate relationships.','六个小理论关注情境与内在动机、内化、因果取向、基本需要、目标内容和关系。CET研究自主支持、信息反馈和适当挑战如何影响内在动机；OIT解释随时间内化；COT关注内部、稳定、可控的因果归因；基本需要理论连接三种需要；目标内容理论区分学习目标和自我目标；关系动机理论关注关怀的教练、队友关系。')],[nb('Theories interconnect: needs influence motivation, causal orientations support internalisation, goals and relationships shape contexts, and contexts influence intrinsic motivation.','这些理论相互连接：需要影响动机，因果取向支持内化，目标与关系塑造情境，情境影响内在动机。')],[nb('Goal content','目标内容', 'Whether goals emphasise learning and mastery or comparison and ego.','目标强调学习掌握还是比较和自我。'),nb('Internalisation','内化', 'The process of becoming more self-determined.','变得更自我确定的过程。')],[],[nb('An athlete attributes success to controllable effort, values training, and experiences supportive relationships, supporting quality motivation.','运动员把成功归因于可控努力，重视训练，并经历支持性关系，从而支持动机质量。')],[nb('Briefly explain the six mini-theories.','简要解释六个小理论。')],[nb('How do the mini-theories connect to a sport context?','六个小理论如何联系运动情境？')])
],examFocus:[nb('Connect needs, context, regulation and outcomes; do not memorise isolated labels without application.')],quickCheck:[nb('How can a controlling reward reduce intrinsic motivation?','控制性奖励如何降低内在动机？')]},
{code:'C.3.3',page:25,theme:'C',title:nb('Motivational climate','动机氛围'),guidingQuestion:nb('How does the environment created by a coach shape motivation?','教练创造的环境如何塑造动机？'),intro:nb('Motivational climate is the psychological environment created through session design, instruction, relationships and feedback. A mastery climate emphasises effort, cooperation, improvement and enjoyment; an ego climate emphasises comparison, winning and ability.','动机氛围是通过课程设计、指导、关系和反馈形成的心理环境。掌握氛围强调努力、合作、进步和享受；自我氛围强调比较、获胜和能力。'),sections:[
ns('Mastery and ego climates',[nb('In a mastery climate, effort, cooperation, improvement and enjoyment are valued. Athletes are more likely to show persistence, confidence, wellbeing, learning and retention. In an ego climate, athletes are compared, winning is prioritised and anxiety, burnout and dropout can increase.','掌握氛围重视努力、合作、进步和享受，运动员更可能表现坚持、自信、福祉、学习和留存。自我氛围强调比较和获胜，焦虑、倦怠和退出可能增加。')],[nb('Climate shapes what athletes think is valued and how they define success.','氛围塑造运动员认为什么有价值以及如何定义成功。')],[nb('Mastery climate','掌握氛围', 'A climate focused on learning, effort, cooperation and personal improvement.','关注学习、努力、合作和个人进步的氛围。'),nb('Ego climate','自我氛围', 'A climate focused on winning, comparison and superiority.','关注获胜、比较和优越的氛围。')],[],[nb('Rewriting “you are the best” to “your effort and strategy improved” reinforces mastery.','把“你是最棒的”改为“你的努力和策略有所进步”可强化掌握氛围。')],[nb('Define motivational climate and list four mastery features.','定义动机氛围并列出四个掌握特征。')],[nb('How can climate affect retention?','氛围如何影响留存？')])
,ns('TARGET framework',[nb('TARGET covers Task, Authority, Recognition, Grouping, Evaluation and Time. Task design, shared decision-making, recognition of effort and strategy, flexible grouping, individual progress feedback and fair time create a mastery climate. Competition, controlling decisions, recognition of winning, ability grouping, public ranking and unequal time create an ego climate.','TARGET包括任务、权威、认可、分组、评价和时间。挑战性学习任务、共同决策、认可努力和策略、灵活分组、个人进步反馈和公平时间形成掌握氛围；竞争、控制式决策、认可获胜、能力强弱分组、公开排名和不平等时间形成自我氛围。')],[nb('Coaches can manipulate these dimensions through what they emphasise, who decides, what is praised, how groups are formed, how performance is evaluated and how time is allocated.','教练可通过强调什么、谁作决定、认可什么、如何分组、如何评价和如何分配时间来调节这些维度。')],[nb('TARGET','TARGET框架', 'Task, Authority, Recognition, Grouping, Evaluation and Time.','任务、权威、认可、分组、评价和时间。')],[],[nb('A coach sets a meaningful challenge, asks athletes for input, praises process, rotates positions, gives individual feedback and ensures fair practice time.','教练设定有意义挑战，征求运动员意见，表扬过程，轮换位置，给予个人反馈并确保公平练习时间。')],[nb('What does each letter in TARGET stand for?','TARGET每个字母代表什么？')],[nb('Give one mastery and one ego example for a TARGET dimension.','为TARGET的一个维度各给一个掌握和自我例子。')])
,ns('Links to motivation and SDT',[nb('Achievement motivation is the desire to meet challenging goals. Self-determination theory explains the quality of motivation through autonomy, competence and relatedness. A mastery climate satisfies these needs and supports intrinsic motivation, persistence and wellbeing; an ego climate can frustrate them.','成就动机是迎接挑战目标的愿望。自我决定理论通过自主、胜任和联结解释动机质量。掌握氛围满足需要并支持内在动机、坚持和福祉；自我氛围可能使需要受挫。')],[nb('In team sports mastery climate builds culture and cohesion, in individual sports it builds confidence, and in youth sport it protects long-term enjoyment and participation.','团队运动中掌握氛围建立文化和凝聚力；个人运动中建立自信；青少年运动中保护长期享受和参与。')],[nb('Long-term participation','长期参与', 'Continued involvement supported by enjoyment, learning and belonging.','由享受、学习和归属支持的持续参与。')],[],[nb('A mastery climate supports both achievement goals and quality motivation rather than replacing one with the other.','掌握氛围同时支持成就目标和动机质量，而不是用其中之一替代另一个。')],[nb('How does a mastery climate satisfy SDT needs?','掌握氛围如何满足自我决定理论的需要？')],[nb('Why can a mastery climate improve long-term participation?','掌握氛围为何能提高长期参与？')])
],examFocus:[nb('Use TARGET accurately and link climate to behaviour, motivation and retention; do not confuse it with other models.')],quickCheck:[nb('What does each letter in TARGET stand for?','TARGET每个字母代表什么？')]},
{code:'C.4.1',page:26,theme:'C',title:nb('Arousal and anxiety','唤醒与焦虑'),guidingQuestion:nb('How do activation and anxiety influence performance?','激活和焦虑如何影响表现？'),intro:nb('Arousal is physical and psychological activation. Drive, inverted-U and catastrophe theories describe different relationships with performance. Anxiety has cognitive and somatic dimensions, and the individual zone of optimal functioning differs by person, task and context.','唤醒是身体和心理的激活。驱力、倒U和灾难理论描述不同的表现关系。焦虑包含认知和躯体维度，最佳功能区因人、任务和情境而异。'),sections:[
ns('Arousal and theories',[nb('Physical arousal can involve higher heart rate, breathing, tension, sweating, adrenaline and available energy. Psychological arousal can involve alertness, attention, processing, motivation and emotion. Drive theory proposes a positive relationship; inverted-U proposes performance improves to an optimum and then declines; IZOF is the individual range where performance is best.','生理唤醒可包括心率、呼吸、肌肉紧张、出汗、肾上腺素和可用能量上升；心理唤醒可包括警觉、注意、加工、动机和情绪。驱力理论提出正向关系；倒U认为表现先改善至最佳再下降；最佳功能区是个人表现最好的唤醒范围。')],[nb('The optimal zone changes with task difficulty, experience, time, fatigue and situation. Power tasks may benefit from higher arousal; precision tasks often need lower to moderate arousal.','最佳区域会随任务难度、经验、时间、疲劳和情境变化。力量型任务可能受益于较高唤醒，精准任务通常需要较低到中等唤醒。')],[nb('Arousal','唤醒', 'Physical and psychological activation.','身体和心理激活。'),nb('IZOF','个体最佳功能区', 'The arousal range in which an individual performs best.','个人表现最佳的唤醒范围。')],[],[nb('A weightlifter may use high arousal, while a golfer may regulate down to support precision.','力量举者可能使用较高唤醒，高尔夫球手则可能调节到较低水平以支持精准。')],[nb('Compare drive, inverted-U and catastrophe predictions.','比较驱力、倒U和灾难理论预测。')],[nb('What is IZOF and why is it individual?','最佳功能区是什么？为什么因人而异？')])
,ns('Anxiety dimensions and catastrophe',[nb('Low anxiety can include excitement, enthusiasm and positive challenge. High anxiety can include fear, worry, nervousness and loss of confidence. Somatic anxiety can energise up to a point, while cognitive anxiety is negative worry and self-doubt. Catastrophe theory predicts performance remains relatively stable until cognitive anxiety is too high, then collapses suddenly.','低焦虑可以包括兴奋、热情和积极挑战；高焦虑可以包括恐惧、担忧、紧张和自信下降。躯体焦虑在一定程度内可以激活表现，认知焦虑则是负面担忧和自我怀疑。灾难理论认为表现相对稳定，直到认知焦虑过高后突然崩溃。')],[nb('Somatic anxiety is not the same as cognitive anxiety: a high heart rate may be useful for a sprint but worry can harm precision.','躯体焦虑不同于认知焦虑：心率升高可能有助于冲刺，但担忧可能损害精准。')],[nb('Cognitive anxiety','认知焦虑', 'Worry, negative thoughts and self-doubt.','担忧、负面想法和自我怀疑。'),nb('Catastrophe','灾难性崩溃', 'A sudden performance collapse when cognitive anxiety is high.','认知焦虑高时的表现突然崩溃。')],[],[nb('A 100 m sprinter can use high somatic arousal but should reduce cognitive worry to avoid the catastrophic drop.','100米冲刺者可以利用较高躯体唤醒，但应减少认知担忧以避免灾难性下降。')],[nb('How do cognitive and somatic anxiety differ?','认知焦虑和躯体焦虑有何不同？')],[nb('What happens in catastrophe theory?','灾难理论认为会发生什么？')])
,ns('Measurement and regulation',[nb('Subjective anxiety can be measured by questionnaires, rating scales and interviews about worry, tension and confidence. Objective indicators include heart rate, blood pressure and galvanic skin response. Using both gives a fuller picture, but self-report can be biased and physiological measures do not identify the thought content by themselves.','主观焦虑可用问卷、量表和访谈测量担忧、紧张与自信。客观指标包括心率、血压和皮电反应。结合两者可获得更完整图景，但自评可能有偏差，生理指标本身不能识别想法内容。')],[nb('Routines, breathing, self-talk and imagery can help regulate arousal.','流程、呼吸、自我对话和意象可以帮助调节唤醒。')],[nb('Galvanic skin response','皮电反应', 'Skin sweat-gland activity used as a physiological indicator.','皮肤汗腺活动，可作为生理指标。')],[],[nb('Before a penalty, use breathing and a short routine, then ask the athlete about worry and confidence as well as heart rate.','罚球前使用呼吸和简短流程，同时询问担忧、自信和心率。')],[nb('Name three objective anxiety measures.','说出三种客观焦虑指标。')],[nb('Why use both subjective and objective measures?','为什么同时使用主观和客观指标？')])
],examFocus:[nb('Do not assume a universal best arousal level; connect theory to task, person and regulation.')],quickCheck:[nb('Compare drive, inverted-U and catastrophe predictions for one performer.','为同一表演者比较驱力、倒U和灾难理论预测。')]},
{code:'C.4.2',page:27,theme:'C',title:nb('Stress and coping','压力与应对'),guidingQuestion:nb('How should athletes match coping strategies to different stressors?','运动员如何将应对策略与不同压力源匹配？'),intro:nb('A stressor creates demand that taxes psychological or physiological resources. Strain can be positive eustress or negative distress. Coping can address the stressor, manage the response or involve avoidance, and effectiveness depends on controllability, person and situation.','压力源产生需求，消耗心理或生理资源。压力反应可以是积极的亢奋，也可以是消极困扰。应对可以处理压力源、管理反应或进行回避；效果取决于可控性、个人和情境。'),sections:[
ns('Stressors and strain',[nb('Common stressors include competition pressure, injury and rehabilitation, academic or work demands, time pressure, selection, travel, finances, goal-setting slumps and relationship issues. Appraising demands and resources determines whether strain is eustress or distress.','常见压力源包括比赛压力、伤病与康复、学业或工作、时间压力、选拔、旅行、财务、目标停滞和人际问题。个体对需求与资源的评价决定压力反应是积极还是消极。')],[nb('Positive strain can energise focus and performance when manageable; negative strain can reduce concentration and confidence and contribute to burnout or injury risk.','可管理的积极压力可以激活注意和表现；消极压力会降低注意和自信，并可能导致倦怠或受伤风险。')],[nb('Stressor','压力源', 'A demand or challenge that taxes resources.','消耗资源的需要或挑战。'),nb('Distress','消极困扰', 'Negative strain that overwhelms or threatens.','压倒或威胁性的消极压力反应。')],[],[nb('A final can be eustress when the athlete sees it as a manageable challenge and has resources; it can become distress if demands exceed perceived control.','运动员把决赛看作可管理的挑战且拥有资源时，压力可能具有激励作用；当需求超过知觉控制时，可能转为消极困扰。')],[nb('Define stressor and strain.','定义压力源和压力反应。')],[nb('Differentiate eustress and distress.','区分积极压力和消极困扰。')])
,ns('Three coping categories',[nb('Problem-focused coping changes a controllable stressor through time management, skill practice, planning, resources or communication. Emotion-focused coping manages thoughts, feelings and arousal through relaxation, self-talk, mindfulness, reframing, breathing and imagery. Avoidance-focused coping escapes or avoids the problem and is rarely helpful long term.','问题聚焦应对通过时间管理、练习、计划、资源或沟通改变可控压力源。情绪聚焦应对通过放松、自我对话、正念、重构、呼吸和意象管理思想、情绪与唤醒。回避聚焦应对逃避问题，长期通常帮助不大。')],[nb('No single strategy works for all stressors; assess controllability and combine problem- and emotion-focused strategies when needed.','没有一种策略适合所有压力源；应评估可控性，必要时结合问题聚焦和情绪聚焦策略。')],[nb('Problem-focused coping','问题聚焦应对', 'Changing the stressor or situation.','改变压力源或情境。'),nb('Emotion-focused coping','情绪聚焦应对', 'Managing the emotional and physiological response.','管理情绪和生理反应。')],[],[nb('For a controllable communication problem, plan a conversation; for weather or an opponent’s ability, use acceptance, routine and self-talk.','可控的沟通问题可安排谈话；天气或对手能力等不可控因素可使用接纳、流程和自我对话。')],[nb('Which strategies lower heart rate and reduce arousal?','哪些策略可以降低心率和唤醒？')],[nb('Name the three coping categories and examples.','说出三类应对及例子。')])
,ns('Decision flow and maladaptive responses',[nb('Ask whether the stressor can be changed. If yes, primarily plan, practise, seek help, set goals, organise and solve the problem. If no, use relaxation, self-talk, imagery, mindfulness, positive reframing, acceptance and focus on process. Maladaptive strategies include withdrawal, venting, self-blame and distraction; they may offer brief relief but reduce support, confidence, motivation and long-term performance.','先判断压力源能否改变。可以改变时主要进行计划、练习、求助、设定目标、组织和问题解决；不能改变时使用放松、自我对话、意象、正念、积极重构、接纳和关注过程。适应不良策略包括退出、发泄、自责和分心；可能短暂缓解，但会降低支持、自信、动机和长期表现。')],[nb('Self-talk should be short, positive, present-tense and realistic, such as “one point at a time” or “I control my effort.”','自我对话应简短、积极、现在时且现实，例如“一次一分”或“我能控制自己的努力”。')],[nb('Avoidance','回避', 'Escaping the stressor rather than addressing or managing it.','逃避而非处理或管理压力源。')],[],[nb('Practise coping in training, review what worked and build a personal toolkit.','在训练中练习应对，复习有效方法并建立个人工具箱。')],[nb('How do you match coping to controllable versus uncontrollable stressors?','如何根据可控和不可控压力源匹配应对？')],[nb('Name four maladaptive coping strategies.','说出四种适应不良应对策略。')])
],examFocus:[nb('Match coping to controllability and consequences; do not memorise every clinical or pharmacological technique.')],quickCheck:[nb('Choose a coping strategy and justify it for a controllable stressor.','为可控压力源选择应对策略并说明理由。')]},
{code:'C.5.1',page:28,theme:'C',title:nb('Goal setting','目标设定'),guidingQuestion:nb('How can goal choice and adjustment direct attention and motivation?','目标选择和调整如何引导注意与动机？'),intro:nb('Goals direct attention, organise effort, provide standards, enable evaluation and influence persistence. IB SEHS groups goals as outcome, performance and process goals. Goals should be adjusted when performance, injury, time, competition or environment changes.','目标引导注意、组织努力、提供标准、支持评价并影响坚持。IB SEHS将目标分为结果、表现和过程目标。表现、伤病、时间、比赛或环境变化时，目标应调整。'),sections:[
ns('Three goal types',[nb('Outcome goals are norm-referenced results such as winning a final or finishing in the top three. Performance goals are self-referenced and measurable, such as swimming 50 m freestyle in 24.50 s. Process goals target controllable technique or strategy, such as a high elbow catch or breathing every three strokes.','结果目标是以常模为参照的结果，如赢得决赛或进入前三；表现目标是以自我为参照且可测量的目标，如50米自由泳24.50秒；过程目标针对可控的技术或策略，如高肘移臂或每三次划水呼吸。')],[nb('Process goals build habits, regulate arousal and reduce worry because the athlete can directly control them.','过程目标因为可控，可以建立习惯、调节唤醒并减少担忧。')],[nb('Outcome goal','结果目标', 'A result compared with others or a required standard.','与他人或要求标准比较的结果。'),nb('Process goal','过程目标', 'A controllable technique or strategy target.','可控的技术或策略目标。')],[],[nb('Running: finish in the top three; run 5 km under 18:30; maintain cadence and relaxed shoulders.','跑步：进入前三；5公里用时低于18:30；保持步频并放松肩膀。')],[nb('Convert an outcome goal into performance and process goals.','把结果目标转换为表现目标和过程目标。')],[nb('What is the key difference between outcome and performance goals?','结果目标和表现目标的关键区别是什么？')])
,ns('Goal purpose and paradox',[nb('Goals direct attention to key cues, motivate effort, improve practice, provide standards and support adjustment. A very high goal can increase effort and performance, but after success the goal may no longer challenge the athlete and drive can deflate. Reflection, new goals and process or mastery goals can support continued motivation.','目标引导关键线索、激励努力、改善练习、提供标准并支持调整。很高目标可增加努力和表现，但成功后目标可能不再有挑战性，动力可能下降。反思、新目标以及过程或掌握目标可支持持续动机。')],[nb('External rewards can replace internal motivation after success, so purpose and reasons for participation should be revisited.','成功后外部奖励可能替代内在动机，因此需要重新思考参与目的和理由。')],[nb('Goal adjustment','目标调整', 'Maintaining, modifying or replacing a goal as context changes.','随着情境变化保持、修改或替换目标。')],[],[nb('After achieving a qualification goal, set a process goal for the next phase and a new performance target.','达到资格目标后，为下一阶段设定过程目标和新表现目标。')],[nb('Explain the goal-setting paradox.','解释目标设定悖论。')],[nb('Why can success reduce drive?','为什么成功可能降低动力？')])
,ns('Adjustment and flexible goals',[nb('Review current performance and context, then maintain, modify or set a new goal and update the plan and strategies. Do-your-best goals focus on maximum effort and best strategies. Open goals focus on experience, exploration and participation without a specific result. These flexible forms can support motivation when circumstances change.','复查当前表现和情境，再保持、修改或设定新目标，并更新计划和策略。尽力目标关注最大努力和最佳策略；开放目标关注体验、探索和参与，不规定具体结果。情境变化时，这些灵活形式可支持动机。')],[nb('A goal may be adjusted because of performance, injury, illness, time constraints, competition changes or environment.','表现、伤病、疾病、时间限制、比赛变化或环境都可能导致目标调整。')],[nb('Open goal','开放目标', 'A flexible goal focused on experience or participation.','关注体验或参与的灵活目标。')],[],[nb('An injured athlete can shift from winning to maintaining quality movement, completing safe rehabilitation and returning gradually.','受伤运动员可从获胜目标转向保持动作质量、完成安全康复并逐步回归。')],[nb('Why are goal adjustment and open goals important?','目标调整和开放目标为何重要？')],[nb('Describe the goal-adjustment steps.','描述目标调整步骤。')])
],examFocus:[nb('Use the IB outcome, performance and process categories; SMART is not the core model.')],quickCheck:[nb('Convert one outcome goal into performance and process goals.','将一个结果目标转换为表现目标和过程目标。')]},
{code:'C.5.2',page:29,theme:'C',title:nb('Imagery','运动意象'),guidingQuestion:nb('How can mental simulation improve sporting performance?','心理模拟如何提高运动表现？'),intro:nb('Imagery is mental simulation of a performance or situation using multiple sensory modalities. It supports cognitive rehearsal and motivational preparation, works best when vivid, controllable, specific and regular, and should be integrated with physical practice and reflection.','意象是使用多种感觉模态对表现或情境的心理模拟。它支持认知演练和动机准备，效果在生动、可控、具体且规律时最好，并应与身体练习和反思结合。'),sections:[
ns('Sensory imagery and functions',[nb('Imagery can use visual, auditory, kinaesthetic, interoceptive, olfactory and gustatory information. Cognitive functions include skill rehearsal and strategy rehearsal, such as refining a serve or anticipating an opponent. Motivational functions include goal setting, arousal regulation, confidence and emotional control.','意象可使用视觉、听觉、动觉、本体感觉、嗅觉和味觉信息。认知功能包括技能演练和策略演练，如完善发球或预判对手；动机功能包括目标设定、唤醒调节、自信和情绪控制。')],[nb('Imagery is not visual-only and is not limited to perfect outcomes. It can include effort, mistakes, recovery, positive and negative scenarios.','意象不只是视觉，也不限于完美结果；可以包含努力、错误、恢复以及积极和消极情境。')],[nb('Skill rehearsal','技能演练', 'Mentally practising the physical execution of a skill.','心理练习技能的物理执行。'),nb('Strategy rehearsal','策略演练', 'Mentally rehearsing tactics, plans and problem solving.','心理演练战术、计划和解决问题。')],[],[nb('A skier imagines turns, edge control, pole-plant timing, the race line, contingency plans, speed and balance.','滑雪者想象转弯、刃控、撑杖时机、线路、备选方案、速度和平衡。')],[nb('Define imagery and explain how it mimics experience.','定义意象并解释它如何模拟体验。')],[nb('Name two sensory modalities in imagery.','说出意象中的两种感觉模态。')])
,ns('PETTLEP and imagery quality',[nb('PETTLEP structures Physical sensations, Environment, Task, Timing, Learning, Emotion and Perspective. The model encourages simulation of physical sensations, the competition setting, specific skill or strategy, timing and sequence, goals and corrective learning, expected emotion and an internal or external viewpoint.','PETTLEP包括身体感觉、环境、任务、时间、学习、情绪和视角。它鼓励模拟身体感觉、比赛环境、具体技能或策略、时间顺序、目标与纠正学习、预期情绪以及内部或外部视角。')],[nb('Vivid, controllable, specific and regular practice is more likely to transfer to performance.','生动、可控、具体且规律的练习更可能迁移到表现。')],[nb('PETTLEP','PETTLEP模型', 'A seven-part structure for designing effective imagery.','设计有效意象的七部分结构。'),nb('Perspective','视角', 'Internal or external viewpoint used in the mental rehearsal.','心理演练中的内部或外部视角。')],[],[nb('Redesign a serve by imagining the actual court, racquet contact sound, physical effort, timing, emotion and a balanced follow-through.','通过想象真实场地、击球声音、身体努力、时间、情绪和平衡随动来重新设计发球意象。')],[nb('Use PETTLEP to redesign an athlete’s serve imagery.','用PETTLEP重新设计运动员的发球意象。')],[nb('Describe the PETTLEP model.','描述PETTLEP模型。')])
,ns('Paivio, specificity and applications',[nb('Paivio’s dual coding framework uses verbal and non-verbal channels, corresponding to cognitive and motivational functions. Imagery can be specific and concrete or general and abstract. Skill acquisition, competition strategy, confidence, motivation and arousal regulation are applications.','Paivio的双编码框架包含语言和非语言通道，分别联系认知和动机功能。意象可以是具体详细，也可以是概括抽象。应用包括技能获得、比赛策略、自信、动机和唤醒调节。')],[nb('Before training, use imagery to plan and focus; before competition, prepare and regulate; after performance, review and learn.','训练前用意象计划和集中；比赛前准备和调节；表现后复查和学习。')],[nb('Specific imagery','具体意象', 'Detailed, concrete and sport-specific rehearsal.','详细、具体且专项的心理演练。'),nb('General imagery','一般意象', 'Broad, abstract and outcome-focused rehearsal.','宽泛、抽象且以结果为重点的演练。')],[],[nb('A skier can see a clean run, hear the wind, feel balance and also imagine correcting a turn after a mistake.','滑雪者可以想象干净完成一圈、听到风声、感到平衡，也可以想象犯错后纠正转弯。')],[nb('Use Paivio to explain cognitive, motivational, specific and general imagery.','用Paivio解释认知、动机、具体和一般意象。')],[nb('Give an example of imagery improving confidence and arousal control.','举出意象提高自信和调节唤醒的例子。')])
],examFocus:[nb('Apply cognitive and motivational functions, PETTLEP and Paivio; include sensation, effort, mistakes and emotion, not just visual imagery.')],quickCheck:[nb('Define imagery and explain how it can improve performance.','定义意象并解释它如何提高表现。')]}
];
